// es.yaml def esFinding
export function esFinding(
  ruleId: RawFinding["ruleId"],
  messageKey: RawFinding["messageKey"],
  start: number,
  end: number,
  alternatives: string[],
  extra?: Partial<RawFinding>,
): RawFinding {
  return { ruleId, messageKey, range: { start, end }, alternatives, ...extra };
}

// es.yaml def esSpan
export function esSpan(ctx: DetectContext, first: SpanishToken, last: SpanishToken): SpanishToken {
  return { ...first, end: last.end, text: ctx.text.slice(first.start, last.end) };
}

// es.yaml def esGreetingBack
export function esGreetingBack(at: SpanishAround, j: number, floor: number): boolean {
  return j < floor || /^[.!?¿;]$/u.test(at.tokens[j].text) || at.tokens[j + 1].broken
    ? false
    : /^(?:hola|buenas|oye)$/u.test(at.tokens[j].lower) || esGreetingBack(at, j - 1, floor);
}

// es.yaml def esGreetingSlot
export function esGreetingSlot(at: SpanishAround) {
  return esGreetingBack(at, at.i - 1, Math.max(0, at.i - 6));
}

// es.yaml def esEndsQuestion
export function esEndsQuestion(at: SpanishAround) {
  const after = at.tokens[at.i + 1];
  return (
    after?.text === "?" ||
    (!!after?.word &&
      (/^(?:hoy|ahora|usted|ustedes)$/u.test(after.lower) || /^\p{Lu}\p{Ll}/u.test(after.text)) &&
      at.tokens[at.i + 2]?.text === "?")
  );
}

// es.yaml def esIsPerfectParticiple
export function esIsPerfectParticiple(word: string) {
  return /o$/u.test(word) && !!esParticiple(word) && !esParticiple(word)!.plural;
}

// es.yaml def esResume
export function esResume(frame: FrameRef, index: number) {
  return frame.resume?.(index) === undefined;
}

// es.yaml def esJoinPrefix
export function esJoinPrefix(prefix: string, word: string) {
  const base = esPlain(prefix);
  return /[aeiou]$/iu.test(base) && word.startsWith("r") && !word.startsWith("rr")
    ? `${base}r${word}`
    : `${base}${word}`;
}

// es.yaml rule es.estarAccents def ES_ESTAR_ASKING
export const ES_ESTAR_ASKING =
  /^(?:s[ée]|sab\p{L}*|sup\p{L}*|pregunt\p{L}*|ver|veamos|dime|dinos|explica\p{L}*)$/u;

// es.yaml rule es.estarAccents def esNameLike
export function esNameLike(at: SpanishAround) {
  const before = at.tokens[at.i - 1];
  if (!(before?.word && !at.tokens[at.i].broken && /^\p{Lu}\p{Ll}/u.test(before.text)))
    return false;
  const word = before.lower;
  return (
    ES_GIVEN_NAMES.has(word) ||
    (word.length > 2 &&
      !esIsNoun(word) &&
      !esAttribute(word) &&
      !esVerbLike(word) &&
      !esIsInfinitive(word) &&
      !ES_PREPOSITIONS.has(word) &&
      !ES_CONJUNCTIONS.has(word) &&
      !ES_DETERMINERS.has(word) &&
      !ES_CLITICS.has(word) &&
      !ES_SER.has(word) &&
      !/mente$/u.test(word))
  );
}

// es.yaml rule es.estarAccents def esAsksBack
export function esAsksBack(at: SpanishAround, j: number, floor: number): boolean {
  return j < floor
    ? false
    : at.tokens[j].text === "¿"
      ? true
      : /^[.;!?…]$/u.test(at.tokens[j].text) || at.tokens[j + 1].broken
        ? false
        : esAsksBack(at, j - 1, floor);
}

// es.yaml rule es.estarAccents def esAsks
export function esAsks(at: SpanishAround) {
  return ES_ESTAR_ASKING.test(at.prev(2)) || esAsksBack(at, at.i - 1, Math.max(0, at.i - 12));
}

// es.yaml rule es.estarAccents def esCloses
export function esCloses(at: SpanishAround, k: number): boolean {
  const after = at.next(k + 1);
  const coordinated = at.next(k + 2);
  return (
    at.endsAfter(k) ||
    ES_PREPOSITIONS.has(after) ||
    ((after === "y" || after === "e") && !esIsNoun(coordinated) && !esAttributeOf(coordinated)) ||
    ((after === "y" || after === "e") &&
      !!esParticiple(at.next(k)) &&
      !!esParticiple(coordinated) &&
      !esIsNoun(coordinated) &&
      esCloses(at, k + 2)) ||
    ES_ESTAR_PLACE_MANNER.has(after) ||
    /^\p{L}{4,}mente$/u.test(after)
  );
}

// es.yaml rule es.estarAccents def esNounPhraseStep
export function esNounPhraseStep(at: SpanishAround, k: number): boolean {
  const word = at.prev(k);
  return k > 3
    ? false
    : ES_DETERMINERS.has(word)
      ? k > 2
      : !ES_PRENOMINAL.has(word.replace(/s$/u, "")) && (!esAttributeOf(word) || esFiniteVerb(word))
        ? false
        : esNounPhraseStep(at, k + 1);
}

// es.yaml rule es.estarAccents def esNounPhraseBefore
export function esNounPhraseBefore(at: SpanishAround) {
  return !!at.prev() && esIsNoun(at.prev()) && esNounPhraseStep(at, 2);
}

// es.yaml rule es.estarAccents def esEstarFinite
export function esEstarFinite(token: SpanishToken) {
  return (
    token.word &&
    (esFiniteVerb(token.lower) ||
      ES_ESTAR_HABER.has(token.lower) ||
      (ES_SER.has(token.lower) && !/^(?:ser|siendo|sido)$/u.test(token.lower)))
  );
}

// es.yaml rule es.estarAccents def esFiniteBefore
export function esFiniteBefore(tokens: SpanishTokens, j: number): boolean {
  return j < 0 ||
    tokens[j + 1].broken ||
    ES_BOUNDARY.test(tokens[j].text) ||
    ES_OPENING.test(tokens[j].text)
    ? false
    : esEstarFinite(tokens[j]) || esFiniteBefore(tokens, j - 1);
}

// es.yaml rule es.estarAccents def esFiniteAfter
export function esFiniteAfter(tokens: SpanishTokens, j: number): boolean {
  return esIsBoundary(tokens[j]) ? false : esEstarFinite(tokens[j]) || esFiniteAfter(tokens, j + 1);
}

// es.yaml rule es.estarAccents def esVerbless
export function esVerbless(at: SpanishAround) {
  return !esFiniteBefore(at.tokens, at.i - 1) && !esFiniteAfter(at.tokens, at.i + 2);
}

// es.yaml rule es.estarAccents def esEstarCounts
export function esEstarCounts(at: SpanishAround, plural: boolean) {
  const count = at.tokens[at.i + 1];
  return (
    !plural &&
    !!count &&
    !count.broken &&
    ((/^\p{N}+$/u.test(count.text) && count.text !== "1") || ES_ESTAR_COUNTS.has(count.lower)) &&
    ((!!at.tokens[at.i + 2]?.word && at.next(2) !== "de") || at.tokens[at.i + 2]?.text === "%")
  );
}

// es.yaml rule es.estarAccents def esEstarAtEnd
export function esEstarAtEnd(at: SpanishAround, plural: boolean, prev: string, prev2: string) {
  if (!at.endsAfter()) return false;
  const subjects = plural ? ES_ESTAR_SUBJECTS_2 : ES_ESTAR_SUBJECTS_3;
  return (
    prev === "no" ||
    (ES_ESTAR_INTERROGATIVES.has(prev) && esAsks(at)) ||
    (prev === "tal" && prev2 === "qué") ||
    (subjects.has(prev) && !ES_PREPOSITIONS.has(prev2)) ||
    ES_ESTAR_PLACE_MANNER.has(prev) ||
    ((prev2 === "qué" || prev2 === "que") &&
      at.tokens[at.i + 1]?.text === "!" &&
      (!!esAttributeOf(prev) ||
        prev === "cerca" ||
        prev === "lejos" ||
        ES_ESTAR_PLACE_MANNER.has(prev))) ||
    (!plural && esAttribute(prev)?.feminine === false && !esAttribute(prev)?.plural)
  );
}

// es.yaml rule es.estarAccents def esEstarSlot
export function esEstarSlot(
  at: SpanishAround,
  plural: boolean,
  prev: string,
  prev2: string,
  next: string,
  reading: ReturnType<typeof esAttributeOf>,
) {
  const subjects = plural ? ES_ESTAR_SUBJECTS_2 : ES_ESTAR_SUBJECTS_3;
  const afterNoun =
    (ES_DETERMINERS.has(prev2) &&
      !!prev &&
      !ES_PREPOSITIONS.has(prev) &&
      !ES_CONJUNCTIONS.has(prev)) ||
    esNounPhraseBefore(at);
  const asked = /^(?:qué|cuál|cuánto|cuánta|cuántos|cuántas)$/u.test(prev2) && esIsNoun(prev);
  const slot =
    asked ||
    at.starts ||
    at.prevIsName ||
    afterNoun ||
    esNameLike(at) ||
    ES_ESTAR_BEFORE_VERB.has(prev) ||
    subjects.has(prev) ||
    ES_ESTAR_INTERROGATIVES.has(prev) ||
    ((esIsNoun(prev) || esAttribute(prev) !== null) && !esVerbLike(prev));
  const nextToken = at.tokens[at.i + 1];
  return afterNoun &&
    reading &&
    !reading.plural &&
    !ES_ESTAR_QUANTIFIERS.has(next) &&
    esCloses(at, 1)
    ? true
    : !slot &&
        (ES_ESTAR_RELATIVES.has(prev) || prev === "que") &&
        reading &&
        !reading.plural &&
        !!esParticiple(next) &&
        (!esIsNoun(next) || /[ai]da$/u.test(next)) &&
        !ES_PARTICIPLE_NOUNS.has(next) &&
        !esVerbLike(next) &&
        esCloses(at, 1)
      ? true
      : !plural &&
          !ES_ESTAR_QUANTIFIERS.has(next) &&
          esVerbless(at) &&
          (((ES_ESTAR_NOT_DETERMINED.has(next) || (next === "fuera" && at.next(2) === "de")) &&
            !at.endsAfter(1)) ||
            (reading &&
              !reading.plural &&
              reading.feminine !== false &&
              esCloses(at, 1) &&
              (at.endsAfter(1) ? !ES_PARTICIPLE_NOUNS.has(next) : !esFiniteVerb(next))))
        ? true
        : !slot
          ? false
          : asked &&
              !plural &&
              ((/^(?:el|la|los|las|mi|su|tu)$/u.test(next) && esIsNoun(at.next(2))) ||
                (/^\p{Lu}\p{Ll}/u.test(nextToken.text) && !nextToken.broken))
            ? true
            : /^(?:el|la|los|las|un|una|mi|su|tu)$/u.test(next) &&
                !esIsBoundary(at.tokens[at.i + 2]) &&
                esIsNoun(at.next(2)) &&
                !esVerbLike(at.next(2)) &&
                !esFiniteVerb(at.next(2)) &&
                !ES_ESTAR_TIME_NOUNS.has(at.next(2))
              ? !at.starts
              : next === "más" &&
                  /^(?:allá|cerca|lejos|adelante|atrás|arriba|abajo)$/u.test(at.next(2))
                ? true
                : next === "al" &&
                    /^(?:lado|fondo|final|norte|sur|este|oeste|borde|otro)$/u.test(at.next(2))
                  ? true
                  : esEstarAfterSlot(
                      at,
                      plural,
                      prev,
                      prev2,
                      next,
                      reading,
                      subjects,
                      afterNoun,
                      nextToken,
                    );
}

// es.yaml rule es.estarAccents def esEstarAfterSlot
export function esEstarAfterSlot(
  at: SpanishAround,
  plural: boolean,
  prev: string,
  prev2: string,
  next: string,
  reading: ReturnType<typeof esAttributeOf>,
  subjects: ReadonlySet<string>,
  afterNoun: boolean,
  nextToken: SpanishToken,
) {
  return ES_ESTAR_TIME.has(next)
    ? esEstarTimeAdverb(at, plural)
    : reading &&
        !reading.plural &&
        !ES_ESTAR_QUANTIFIERS.has(next) &&
        !ES_PARTICIPLE_NOUNS.has(next) &&
        !esVerbLike(next) &&
        (!esIsNoun(next) ||
          ES_INVARIANT.has(next) ||
          (!!esParticiple(next) && /[ai]da$/u.test(next))) &&
        (esCloses(at, 1) ||
          (ES_ESTAR_BEFORE_VERB.has(prev) && !!esParticiple(next) && !esIsNoun(next)))
      ? true
      : ES_ESTAR_PLACE_MANNER.has(next)
        ? !ES_CLITICS.has(at.next(2)) && at.next(2) !== "la"
        : next === "cerca" || next === "lejos"
          ? at.next(2) === "de" || at.endsAfter(1)
          : ES_ESTAR_DEGREE.has(next)
            ? (ES_ESTAR_PLACE_MANNER.has(at.next(2)) ||
                at.next(2) === "cerca" ||
                at.next(2) === "lejos" ||
                !!esAttributeOf(at.next(2))) &&
              (next === "muy" || !esIsNoun(at.next(2)) || ES_INVARIANT.has(at.next(2))) &&
              !esIsNoun(at.next(3))
            : ES_ESTAR_PREPOSITIONS.has(next)
              ? !ES_ESTAR_PARENTHETICAL.has(at.next(2))
              : (next === "al" || next === "a") && (afterNoun || subjects.has(prev))
                ? !ES_CLITICS.has(at.next(2)) && !esIsInfinitive(at.next(2))
                : prev === "no"
                  ? !esIsNoun(next) && !ES_CLITICS.has(next)
                  : ES_ESTAR_INTERROGATIVES.has(prev) ||
                      subjects.has(prev) ||
                      (prev === "tal" && prev2 === "qué")
                    ? (!esIsNoun(next) ||
                        ES_DETERMINERS.has(next) ||
                        /^\p{Lu}/u.test(nextToken.text)) &&
                      !ES_CLITICS.has(next)
                    : false;
}

// es.yaml rule es.estarAccents def esEstarTimeAdverb
export function esEstarTimeAdverb(at: SpanishAround, plural: boolean) {
  const after = at.next(2);
  const later = esAttributeOf(after);
  return esIsGerund(after)
    ? true
    : later && !later.plural && later.feminine !== null && (plural || !later.feminine)
      ? !ES_ESTAR_QUANTIFIERS.has(after)
      : !!later && !later.plural && !esIsNoun(after) && !esVerbLike(after) && esCloses(at, 2);
}

// es.yaml rule es.estarAccents def esEstarBeforeWord
export function esEstarBeforeWord(
  at: SpanishAround,
  plural: boolean,
  prev: string,
  prev2: string,
  next: string,
) {
  const reading = esAttributeOf(next);
  return esIsGerund(next)
    ? true
    : next === "de"
      ? ES_ESTAR_DE.has(at.next(2))
      : /^\p{L}{4,}mente$/u.test(next)
        ? !ES_CONJUNCTIONS.has(prev) || prev === "que"
        : reading &&
            !ES_ESTAR_QUANTIFIERS.has(next) &&
            reading.feminine !== null &&
            !reading.plural &&
            (plural || !reading.feminine)
          ? true
          : ES_ESTAR_QUANTIFIERS.has(next) && (next === "solo" || next === "todo")
            ? at.endsAfter(1) ||
              ES_ESTAR_PLACE_MANNER.has(at.next(2)) ||
              ES_ESTAR_DEGREE.has(at.next(2))
            : esEstarSlot(at, plural, prev, prev2, next, reading);
}

// es.yaml rule es.estarAccents def esEstarReading
export function esEstarReading(at: SpanishAround, plural: boolean) {
  const prev = at.prev();
  const prev2 = at.prev(2);
  const next = at.next();
  return prev === "como" &&
    !next &&
    at.endsAfter() &&
    [2, 3, 4, 5].some((k) => /^(?:d[eé]j|qued)\p{L}*$/u.test(at.prev(k)))
    ? true
    : prev === "como" && esGreetingSlot(esAround(at.tokens, at.i - 1)) && esEndsQuestion(at)
      ? true
      : ES_PREPOSITIONS.has(prev) || ES_SER.has(prev) || esIsInfinitive(prev) || prev === "como"
        ? false
        : /^tod[oa]s?$/u.test(prev)
          ? false
          : !next && at.endsAfter() && !plural && esParticiple(prev)?.feminine === false
            ? true
            : esParticiple(prev) && esAround(at.tokens, at.i - 1).starts
              ? false
              : ES_CLITICS.has(prev) && prev !== "la" && prev !== "las"
                ? true
                : esEstarCounts(at, plural)
                  ? true
                  : !next
                    ? esEstarAtEnd(at, plural, prev, prev2)
                    : esEstarBeforeWord(at, plural, prev, prev2, next);
}

// es.yaml rule es.estarAccents def esDistantTrigger
export function esDistantTrigger(at: SpanishAround) {
  const next = at.next();
  return (
    at.tokens[at.i].lower === "este" &&
    [2, 3, 4].some(
      (k) =>
        ES_SUBJUNCTIVE_TRIGGERS.has(at.prev(k)) &&
        !/^(?:dij|dic|dec|cre|pens|piens|sab|sé|afirm|asegur|explic|cuent|cont)\p{L}*$/u.test(
          at.prev(k + 1),
        ),
    ) &&
    ((!!esParticiple(next)?.feminine && !esIsNoun(next)) || (next === "a" && at.next(2) === "la"))
  );
}

// es.yaml rule es.estarAccents def esSubjunctiveReading
export function esSubjunctiveReading(at: SpanishAround) {
  const prev = at.prev();
  const prev2 = at.prev(2);
  const clitic = ES_CLITICS.has(prev) && prev !== "la" && prev !== "las" && prev !== "los";
  const prev3 = at.prev(3);
  const trigger =
    clitic ||
    ES_SUBJUNCTIVE_TRIGGERS.has(prev) ||
    (prev === "vez" && prev2 === "tal") ||
    (prev === "pronto" && prev2 === "tan") ||
    (prev === "no" && ES_SUBJUNCTIVE_TRIGGERS.has(prev2)) ||
    (ES_SUBJUNCTIVE_TRIGGERS.has(prev3) &&
      ES_DETERMINERS.has(prev2) &&
      !!prev &&
      !ES_CLITICS.has(prev2));
  const next = at.next();
  const reading = esAttributeOf(next);
  return !trigger
    ? esDistantTrigger(at)
    : !next
      ? clitic && at.endsAfter()
      : esIsGerund(next)
        ? true
        : ES_ESTAR_PLACE_MANNER.has(next)
          ? esCloses(at, 1)
          : next === "de"
            ? ES_ESTAR_DE.has(at.next(2))
            : ES_ESTAR_PREPOSITIONS.has(next) || next === "al"
              ? !ES_ESTAR_PARENTHETICAL.has(at.next(2))
              : next === "por" || next === "a"
                ? /^(?:encima|debajo|punto|tiempo)$/u.test(at.next(2))
                : at.tokens[at.i].lower === "este" &&
                    esParticiple(next)?.feminine &&
                    !esIsNoun(next)
                  ? true
                  : next === "cerca" || next === "lejos"
                    ? at.next(2) === "de"
                    : ES_ESTAR_DEGREE.has(next)
                      ? !!esAttributeOf(at.next(2)) && esCloses(at, 2)
                      : !!reading &&
                        !ES_ESTAR_QUANTIFIERS.has(next) &&
                        !ES_PARTICIPLE_NOUNS.has(next) &&
                        !(esVerbLike(next) && !next.endsWith("o")) &&
                        esCloses(at, 1);
}

// es.yaml rule es.estarAccents def esDemonstrativeReading
export function esDemonstrativeReading(at: SpanishAround) {
  const prev = at.prev();
  const next = at.next();
  if (!next) return false;
  const form = at.tokens[at.i].lower;
  return /^mism[oa]s?$/u.test(next)
    ? true
    : ES_PREPOSITIONS.has(prev) && !/^(?:a|al|del|según|hasta)$/u.test(prev)
      ? (esIsNoun(next) || (!!esGenderedForm(next) && !esParticiple(next))) &&
        !ES_NOT_AFTER_DEMONSTRATIVE.has(next) &&
        !esIsGerund(next)
      : esAttributeOf(next) || ES_NOT_AFTER_DEMONSTRATIVE.has(next) || !esIsNoun(next)
        ? false
        : form === "está"
          ? at.next(2) !== "de" &&
            (/(?:ión|dad|tud)$/u.test(next) || (/a$/u.test(next) && esIsInfinitive(prev)))
          : form === "estás" && /as$/u.test(next);
}

// es.yaml rule es.diacritics def ES_DIA_KNOWING
export const ES_DIA_KNOWING =
  /^(?:sé|sabe|sabes|sabemos|saben|sabéis|sabía|sabías|sabían|sabíamos|saber|sabiendo|sabido|sabrá|sabré|sabría|supe|supo|supieron|supiera|supiéramos|pregunt\p{L}*|decidir|decide|decidió|decidieron|elegir|explica|explícame|explíqueme|explicar|imagin\p{L}*|recuerdo|recuerda|recordaba|averiguar|entender|entiendo|ignoro|dime|dinos)$/u;

// es.yaml rule es.diacritics def ES_DIA_ASKING
export const ES_DIA_ASKING =
  /^(?:sé|sabe|sabes|sabemos|saben|sabía|sabías|sabían|saber|pregunt\p{L}*|decidir|elegir|averiguar|se)$/u;

// es.yaml rule es.diacritics def ES_AFFECTION
export const ES_AFFECTION =
  /^(?:quier[eo]|quieres|quieren|ama|amas|aman|adora|adoras|adoran|odia|odias|odian)$/u;

// es.yaml rule es.diacritics def ES_EVENT
export const ES_EVENT = /^(?:pas|ocurr|suced)(?:a|ó|aba|ará|ará|ía|e|ió|erá|irá|ado|ido)$/u;

// es.yaml rule es.diacritics def ES_DEED
export const ES_DEED =
  /^(?:hacer|hacerles?|hago|haces|hace|hacemos|hacen|hice|hiciste|hizo|hicimos|hicieron|hecho|haré|harás|hará|haría|harías)$/u;

// es.yaml rule es.diacritics def ES_BEFORE_DEED
export const ES_BEFORE_DEED =
  /^(?:puedo|puedes|puede|podemos|pueden|podría|podrías|debo|debes|debe|debemos|deben|quiero|quieres|quiere|queremos|quieren|voy|vas|va|vamos|van|tengo|tienes|tiene|tenemos|tienen|he|has|ha|hemos|han|había|habías|habían)$/u;

// es.yaml rule es.diacritics def ES_PRETERITE
export const ES_PRETERITE = /^\p{L}{2,}(?:é|ó|aste|iste|ió|aron|ieron)$/u;

// es.yaml rule es.diacritics def esKnownNominal
export function esKnownNominal(word: string) {
  return esIsNoun(word) || !!esAttributeOf(word) || esIsGenderedEntry(word);
}

// es.yaml rule es.diacritics def esOpensQuestion
export function esOpensQuestion(at: SpanishAround): "?" | "!" | null {
  const j1 = ES_PREPOSITIONS.has(at.prev(1)) && !at.tokens[at.i].broken ? at.i - 2 : at.i - 1;
  const j = ES_QUESTION_LEAD.has(at.tokens[j1]?.lower ?? "") && at.tokens[j1]?.word ? j1 - 1 : j1;
  const mark = at.tokens[j];
  if (!(mark && !(j < at.i - 1 && at.tokens[j + 1].broken))) return null;
  return mark.text === "¿" ? "?" : mark.text === "¡" ? "!" : null;
}

// es.yaml rule es.diacritics def esSolidNoun
export function esSolidNoun(word: string) {
  return (
    !!word &&
    esIsNoun(word) &&
    !esAttributeOf(word) &&
    !(esVerbLike(word) && !word.endsWith("o")) &&
    !esSecondPersonVerb(word) &&
    !esSubjunctiveLike(word) &&
    !esIsInfinitive(word) &&
    !ES_DIA_FINITE.has(word) &&
    !ES_DIA_NOT_NOUNS.has(word) &&
    !ES_DETERMINERS.has(word)
  );
}

// es.yaml rule es.diacritics def esEchoQuestion
export function esEchoQuestion(
  at: SpanishAround,
  j: number,
  haber: boolean,
  afterPreposition: boolean,
): boolean {
  if (!(j < at.tokens.length && j < at.i + 12)) return false;
  const token = at.tokens[j];
  const word = token.lower;
  return token.broken || token.text === "?" || /^[.!;]$/u.test(token.text)
    ? false
    : !token.word
      ? /^\p{N}/u.test(token.text) || esEchoQuestion(at, j + 1, haber, afterPreposition)
      : (j > at.i + 1 && /^\p{Lu}/u.test(token.text)) ||
          ES_DETERMINERS.has(word) ||
          ES_DIA_SUBJECTS.has(word) ||
          word === "que" ||
          word === "no" ||
          (/[áéíóú]/u.test(word) && ES_ASKED_FORMS.has(word)) ||
          /^\p{L}{4,}mente$/u.test(word) ||
          ((j === at.i + 1 || (ES_CLITICS.has(at.tokens[j - 1].lower) && !haber)) &&
            esSubjunctiveLike(word)) ||
          (!!esAttributeOf(word) &&
            !haber &&
            !esIsGerund(word) &&
            !(ES_CLITICS.has(at.tokens[j - 1].lower) && esVerbLike(word))) ||
          (esSolidNoun(word) && !afterPreposition)
        ? true
        : esEchoQuestion(
            at,
            j + 1,
            /^(?:he|has|ha|hemos|habéis|han|había|habías|habían)$/u.test(word),
            ES_PREPOSITIONS.has(word),
          );
}

// es.yaml rule es.diacritics def esEchoClause
export function esEchoClause(at: SpanishAround) {
  const k = at.next(1) === "no" ? 2 : 1;
  const first = at.next(k);
  return /^(?:me|te|lo|la|nos|os|los|las)$/u.test(first) && ES_AFFECTION.test(at.next(k + 1))
    ? at.endsAfter(k + 1)
    : /^(?:estás|está|están|estáis|estamos|estaba|estabas|estaban)$/u.test(first)
      ? esIsGerund(at.next(k + 1)) && !ES_ASKED_GERUNDS.has(at.next(k + 1)) && at.endsAfter(k + 1)
      : false;
}

// es.yaml rule es.diacritics def esPurposeClause
export function esPurposeClause(at: SpanishAround, j: number): boolean {
  if (!(j < at.tokens.length && j < at.i + 12)) return false;
  return at.tokens[j].broken || /^[?.!;]$/u.test(at.tokens[j].text)
    ? false
    : (at.tokens[j].word &&
        esSubjunctiveLike(at.tokens[j].lower) &&
        !esIsNoun(at.tokens[j].lower)) ||
        esPurposeClause(at, j + 1);
}

// es.yaml rule es.diacritics def esWishAfter
export function esWishAfter(at: SpanishAround, k: number): boolean {
  return ES_CLITICS.has(at.next(k)) || at.next(k) === "no"
    ? esWishAfter(at, k + 1)
    : esSubjunctiveLike(at.next(k));
}

// es.yaml rule es.diacritics def esShortClause
export function esShortClause(at: SpanishAround, k: number, n: number): boolean {
  const word = at.next(k + n);
  return n > 8
    ? false
    : at.endsAfter(k + n - 1)
      ? true
      : !word || ES_DIA_FINITE.has(word) || word === "está" || word === "que"
        ? false
        : n > 4 && esFiniteVerb(word) && !esIsNoun(word) && !esAttributeOf(word)
          ? false
          : esShortClause(at, k, n + 1);
}

// es.yaml rule es.diacritics def esFiniteNotNoun
export function esFiniteNotNoun(word: string) {
  return (
    ES_DIA_FINITE.has(word) ||
    /^(?:hay|he|has|ha|hemos|han|había|habían)$/u.test(word) ||
    esFiniteVerb(word)
  );
}

// es.yaml rule es.diacritics def esInQuestionBack
export function esInQuestionBack(at: SpanishAround, j: number, floor: number): boolean {
  return j < floor
    ? false
    : at.tokens[j].text === "¿"
      ? true
      : /^[.!?;]$/u.test(at.tokens[j].text) || at.tokens[j + 1].broken
        ? false
        : esInQuestionBack(at, j - 1, floor);
}

// es.yaml rule es.diacritics def esInQuestion
export function esInQuestion(at: SpanishAround) {
  return esInQuestionBack(at, at.i - 1, Math.max(0, at.i - 16));
}

// es.yaml rule es.diacritics def esPlaceStep
export function esPlaceStep(at: SpanishAround, k: number, content: number, room: number): boolean {
  const word = at.next(k);
  return k > 9
    ? false
    : at.endsAfter(k - 1)
      ? true
      : !word
        ? false
        : ES_PREPOSITIONS.has(word)
          ? esPlaceStep(at, k + 1, 0, /^(?:al|del)$/u.test(word) ? 3 : 1)
          : ES_DETERMINERS.has(word) || ES_DIA_SUBJECTS.has(word) || ES_DIA_QUANTITY.has(word)
            ? content
              ? false
              : esPlaceStep(at, k + 1, content, 3)
            : esFiniteNotNoun(word) && !esIsNoun(word)
              ? false
              : content + 1 > room
                ? false
                : esPlaceStep(at, k + 1, content + 1, room);
}

// es.yaml rule es.diacritics def esMissingThing
export function esMissingThing(at: SpanishAround) {
  return ES_EXISTS.has(at.next()) && ES_PLACE_START.has(at.next(2)) && esPlaceStep(at, 3, 0, 1);
}

// es.yaml rule es.diacritics def esUntoldEvent
export function esUntoldEvent(at: SpanishAround) {
  const k1 = ES_CLITICS.has(at.next(1)) ? 2 : 1;
  const k = /^(?:ha|había|habrá|habría)$/u.test(at.next(k1)) ? k1 + 1 : k1;
  if (!ES_EVENT.test(at.next(k))) return false;
  return at.endsAfter(ES_AFTER_EVENT.has(at.next(k + 1)) ? k + 1 : k);
}

// es.yaml rule es.diacritics def esUntoldDeed
export function esUntoldDeed(at: SpanishAround) {
  const k1 = /^(?:me|te|le|les|nos|os)$/u.test(at.next(1)) ? 2 : 1;
  const k2 = ES_BEFORE_DEED.test(at.next(k1))
    ? /^(?:a|que)$/u.test(at.next(k1 + 1))
      ? k1 + 2
      : k1 + 1
    : k1;
  if (!ES_DEED.test(at.next(k2))) return false;
  return at.endsAfter(k2) || ES_AFTER_DEED.has(at.next(k2 + 1));
}

// es.yaml rule es.diacritics def esMark0
export function esMark0(at: SpanishAround) {
  return esOpensQuestion(at) !== null || esInQuestion(at);
}

// es.yaml rule es.diacritics def esAskedQuestion
export function esAskedQuestion(
  at: SpanishAround,
  word: string,
  accented: string,
  prev: string,
  next: string,
) {
  return word === "como" && (ES_DETERMINERS.has(next) || next === "para" || /[áéíóú]/u.test(next))
    ? null
    : (word === "cuando" || word === "como") && esWishAfter(at, 1)
      ? null
      : word !== "que"
        ? accented
        : prev === "a"
          ? esSolidNoun(next)
            ? accented
            : null
          : ES_PREPOSITIONS.has(prev)
            ? esPurposeClause(at, at.i + 1) || ES_DETERMINERS.has(next)
              ? null
              : accented
            : next === "tal" || (esSolidNoun(next) && !ES_DETERMINERS.has(next))
              ? accented
              : esEchoQuestion(at, at.i + 1, false, false) || esEchoClause(at)
                ? null
                : accented;
}

// es.yaml rule es.diacritics def esExclaimed
export function esExclaimed(at: SpanishAround, word: string, accented: string, next: string) {
  return word !== "que" && word !== "como" && word !== "cuan"
    ? null
    : ES_CLITICS.has(next) && word === "que"
      ? null
      : word === "como" && next === "no" && !esWishAfter(at, 1)
        ? accented
        : word === "como"
          ? /^(?:me|te|nos|os)$/u.test(next) &&
            !/^(?:he|has|ha)$/u.test(at.next(2)) &&
            !esWishAfter(at, 1)
            ? accented
            : null
          : word === "cuan"
            ? accented
            : next &&
                !esSubjunctiveLike(next) &&
                next !== "sí" &&
                next !== "no" &&
                (esIsNoun(next) ||
                  !!esAttributeOf(next) ||
                  ES_ADVERBIALS.has(next) ||
                  next === "tan" ||
                  next === "más")
              ? accented
              : null;
}

// es.yaml rule es.diacritics def esKnowingQuestion
export function esKnowingQuestion(
  at: SpanishAround,
  word: string,
  accented: string,
  prev: string,
  next: string,
  nextToken: SpanishToken | undefined,
): string | null | undefined {
  return !next
    ? null
    : esIsInfinitive(next)
      ? esShortClause(at, 1, 1)
        ? accented
        : null
      : word === "que" && (esIsNoun(next) || !!esAttributeOf(next)) && esIsInfinitive(at.next(2))
        ? esShortClause(at, 2, 1)
          ? accented
          : null
        : word === "que"
          ? ES_DIA_ASKING.test(prev) && esSolidNoun(next) && !next.endsWith("s")
            ? accented
            : null
          : word === "donde" || word === "adonde" || word === "quien" || word === "quienes"
            ? ES_CLITICS.has(next) || !!nextToken?.word
              ? accented
              : null
            : word === "cual" || word === "cuales"
              ? /^(?:es|son|era|eran|fue|será|sería|de)$/u.test(next)
                ? accented
                : null
              : undefined;
}

// es.yaml rule es.diacritics def esInterrogativeTail
export function esInterrogativeTail(
  at: SpanishAround,
  word: string,
  accented: string,
  prev: string,
  next: string,
) {
  const before = at.tokens[at.i - 1];
  const sentenceStart = !before || at.tokens[at.i].broken || /^[.!?…]$/u.test(before.text);
  const closes = at.endsAfter(1) || /^(?:tan|más|es|son|era|está|estaba)$/u.test(at.next(2));
  return (word === "que" || word === "quien" || word === "quienes") &&
    /^(?:a|de|con|en|sobre)$/u.test(prev) &&
    ES_DIA_KNOWING.test(at.prev(2)) &&
    !esInQuestion(at) &&
    next &&
    !ES_DETERMINERS.has(next)
    ? accented
    : word === "que" &&
        /^(?:a|de|en|hasta|por|con|desde)$/u.test(prev) &&
        ES_QUESTION_NOUNS.has(next) &&
        !/^(?:de|que)$/u.test(at.next(2))
      ? accented
      : word === "que" &&
          sentenceStart &&
          next &&
          !esSubjunctiveLike(next) &&
          !ES_CLITICS.has(next) &&
          closes &&
          (!!esAttributeOf(next) || (esIsNoun(next) && !esVerbLike(next))) &&
          next !== "no"
        ? accented
        : null;
}

// es.yaml rule es.diacritics def esInterrogativeRest
export function esInterrogativeRest(
  at: SpanishAround,
  word: string,
  accented: string,
  prev: string,
  next: string,
  nextToken: SpanishToken | undefined,
) {
  const knowing =
    ES_DIA_KNOWING.test(prev) || (prev === "se" && /^(?:no|yo|lo|ya)$/u.test(at.prev(2)))
      ? esKnowingQuestion(at, word, accented, prev, next, nextToken)
      : undefined;
  return word === "que" &&
    /^(?:tú|usted|ustedes|vosotros|vosotras|ellos|ellas|él|ella|esto|eso|aquello|ahora|entonces)$/u.test(
      prev,
    ) &&
    esOpensQuestion(esAround(at.tokens, at.i - 1)) === "?" &&
    (!next || !esWishAfter(at, 1))
    ? accented
    : word === "que" &&
        /^[.!?]$/u.test(nextToken?.text ?? "") &&
        !nextToken!.broken &&
        at.tokens[at.i + 2]?.text !== "." &&
        (ES_PREPOSITIONS.has(prev) || ES_DIA_KNOWING.test(prev) || esIsInfinitive(prev))
      ? accented
      : word === "que" &&
          prev === "sé" &&
          /^(?:no|ni)$/u.test(at.prev(2)) &&
          !esInQuestion(at) &&
          !!(ES_CLITICS.has(next) ? at.next(2) : next) &&
          esFiniteNotNoun(ES_CLITICS.has(next) ? at.next(2) : next) &&
          !esSubjunctiveLike(ES_CLITICS.has(next) ? at.next(2) : next)
        ? accented
        : word === "que" &&
            /^pregunt\p{L}*$/u.test(prev) &&
            /^(?:me|te|se|nos|os)$/u.test(at.prev(2)) &&
            !!next &&
            esFiniteNotNoun(next) &&
            !esIsNoun(next) &&
            !esSubjunctiveLike(next)
          ? accented
          : word === "que" &&
              (ES_DIA_KNOWING.test(prev) || /^(?:ver|veamos|mira|mirar)$/u.test(prev)) &&
              (esMissingThing(at) || esUntoldEvent(at) || esUntoldDeed(at))
            ? accented
            : knowing !== undefined
              ? knowing
              : esInterrogativeTail(at, word, accented, prev, next);
}

// es.yaml rule es.diacritics def esInterrogative
export function esInterrogative(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const accented = Object.hasOwn(ES_INTERROGATIVE, word) ? ES_INTERROGATIVE[word] : undefined;
  if (!accented) return null;
  const next = at.next();
  const nextToken = at.tokens[at.i + 1];
  const prev = at.prev();
  const mark = esOpensQuestion(at);
  return prev === "el" &&
    !/^cua(?:n|l|les)$/u.test(word) &&
    ((at.endsAfter() && word !== "que") || /^(?:sino|ni|y|e|o|u)$/u.test(next)) &&
    !nextToken?.broken
    ? accented
    : word === "como" &&
        !esMark0(at) &&
        esGreetingSlot(at) &&
        /^(?:estas|esta|estás|está|están|estan|estáis|estais)$/u.test(next) &&
        esEndsQuestion(esAround(at.tokens, at.i + 1))
      ? accented
      : word === "que" &&
          ((/^(?:y|e|o|u|ni)$/u.test(next) &&
            /[áéíóú]/u.test(at.next(2)) &&
            ES_ASKED_FORMS.has(at.next(2))) ||
            (/^(?:y|e|o|u|ni)$/u.test(prev) &&
              /[áéíóú]/u.test(at.prev(2)) &&
              ES_ASKED_FORMS.has(at.prev(2))))
        ? accented
        : mark === "?"
          ? esAskedQuestion(at, word, accented, prev, next)
          : mark === "!"
            ? esExclaimed(at, word, accented, next)
            : esInterrogativeRest(at, word, accented, prev, next, nextToken);
}

// es.yaml rule es.diacritics def esRelative
export function esRelative(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const plainForm = Object.hasOwn(ES_PLAIN_RELATIVE, word) ? ES_PLAIN_RELATIVE[word] : undefined;
  if (!(plainForm && at.tokens[at.i - 1]?.text !== "¿")) return null;
  const k = ES_PREPOSITIONS.has(at.prev()) ? 2 : 1;
  const antecedent = at.prev(k);
  return ES_QUANTITY_ANTECEDENTS.has(antecedent) && esIsInfinitive(at.next())
    ? plainForm
    : Object.hasOwn(ES_NOUN_ANTECEDENTS, word) &&
        ES_NOUN_ANTECEDENTS[word].includes(antecedent) &&
        (k === 1 || word === "dónde") &&
        !!at.next()
      ? plainForm
      : null;
}

// es.yaml rule es.diacritics def esNotNounPhrase
export function esNotNounPhrase(word: string) {
  return (
    !ES_BEFORE_NOUN.has(word) &&
    (ES_ONLY_VERBS.has(word) ||
      ES_DETERMINERS.has(word) ||
      ES_PREPOSITIONS.has(word) ||
      ES_DIA_NUMBERS.has(word) ||
      /^(?:algo|nada|esto|eso|también|tampoco)$/u.test(word) ||
      ((esVerbLike(word) ||
        ES_DIA_FINITE.has(word) ||
        ES_COMMON_VERBS.has(word) ||
        esSecondPersonVerb(word)) &&
        !esIsNoun(word) &&
        !esAttributeOf(word)))
  );
}

// es.yaml rule es.diacritics def esGiveObject
export function esGiveObject(at: SpanishAround) {
  const k = /^(?:su|sus|tu|tus|mi|mis)$/u.test(at.next()) ? 2 : 1;
  return (
    (ES_GIVEN.has(at.next(k)) &&
      (at.endsAfter(k) || /^(?:de|del|a|al|por|para|y)$/u.test(at.next(k + 1)))) ||
    (/^(?:un|una)$/u.test(at.next()) && ES_GIVEN_WITH_ARTICLE.has(at.next(2))) ||
    (at.next() === "a" && at.next(2) === "luz") ||
    /^(?:con|según)$/u.test(at.next())
  );
}

// es.yaml rule es.diacritics def esSubjectFillers
export function esSubjectFillers(at: SpanishAround, k: number): number {
  return k <= 3 && ES_SUBJECT_FILLERS.has(at.prev(k)) ? esSubjectFillers(at, k + 1) : k;
}

// es.yaml rule es.diacritics def esSubjunctiveSlot
export function esSubjunctiveSlot(at: SpanishAround) {
  const k = esSubjectFillers(at, 1);
  return (
    /^(?:que|ojalá|quien|aunque|cuando)$/u.test(at.prev(k)) &&
    !/^(?:más|menos|antes|mejor|peor|tal|así|ya)$/u.test(at.prev(k + 1))
  );
}

// es.yaml rule es.diacritics def esFiniteForm
export function esFiniteForm(word: string) {
  return !!word && (ES_DIA_FINITE.has(word) || esFiniteVerb(word));
}

// es.yaml rule es.diacritics def esParticipleOf
export function esParticipleOf(word: string) {
  return !!word && !!esParticiple(word);
}

// es.yaml rule es.diacritics def esPlainInfinitive
export function esPlainInfinitive(word: string) {
  return /^\p{L}+[aeií]r$/u.test(word) && esIsInfinitive(word);
}

// es.yaml rule es.diacritics def esConcessive
export function esConcessive(at: SpanishAround, k: number): boolean {
  const token = at.tokens[at.i + k];
  return k > 6 || !token || token.broken || /^[.;:!?]$/u.test(token.text)
    ? false
    : token.text === ","
      ? k > 1
      : k > 1 && token.word && ES_DIA_FINITE.has(token.lower)
        ? false
        : esConcessive(at, k + 1);
}

// es.yaml rule es.diacritics def esEndsPlainly
export function esEndsPlainly(at: SpanishAround, n: number, last: number): boolean {
  const token = at.tokens[at.i + n];
  return n > last
    ? false
    : !token || token.broken || /^[.!?]$/u.test(token.text)
      ? true
      : !token.word || ES_DIA_FINITE.has(token.lower) || esFiniteVerb(token.lower)
        ? false
        : esEndsPlainly(at, n + 1, last);
}

// es.yaml rule es.diacritics def esSkipClitics
export function esSkipClitics(at: SpanishAround, k: number, limit: number): number {
  return k < limit && ES_CLITICS.has(at.next(k)) ? esSkipClitics(at, k + 1, limit) : k;
}

// es.yaml rule es.diacritics def esPastFact
export function esPastFact(at: SpanishAround, firstPerson: boolean) {
  const k = esSkipClitics(at, 1, 3);
  const verb = at.next(k);
  return firstPerson
    ? verb === "he"
      ? !!esParticiple(at.next(k + 1))
      : /^(?:hice|fui|tuve|dije|puse|vine|estuve|pude|quise|supe)$/u.test(verb) ||
        (/^\p{L}{2,}é$/u.test(verb) && esFiniteVerb(verb) && !esIsNoun(verb))
    : ES_IRREGULAR_PAST.has(verb) ||
        (ES_PRETERITE.test(verb) && esFiniteVerb(verb) && !esIsNoun(verb))
      ? true
      : /^(?:he|has|ha|hemos|han)$/u.test(verb) && !!esParticiple(at.next(k + 1));
}

// es.yaml rule es.diacritics def esPlainSentence
export function esPlainSentence(at: SpanishAround, j: number): boolean {
  if (!(j < at.tokens.length && j < at.i + 16)) return false;
  const token = at.tokens[j];
  return token.broken
    ? false
    : token.text === "."
      ? at.tokens[j + 1]?.text !== "."
      : !token.word || /^(?:si|que|pero|porque|cuando|aunque)$/u.test(token.lower)
        ? false
        : esPlainSentence(at, j + 1);
}

// es.yaml rule es.diacritics def esDeniedBefore
export function esDeniedBefore(at: SpanishAround, j: number, floor: number): boolean {
  return j < floor
    ? false
    : /^[.!?;]$/u.test(at.tokens[j].text) || at.tokens[j + 1].broken
      ? false
      : at.tokens[j].lower === "no" || esDeniedBefore(at, j - 1, floor);
}

// es.yaml rule es.diacritics def esFiniteCount
export function esFiniteCount(at: SpanishAround, j: number): number {
  if (!(j < at.tokens.length && j < at.i + 16)) return 0;
  const token = at.tokens[j];
  return token.broken || /^[.!?]$/u.test(token.text)
    ? 0
    : ((token.word && esFiniteForm(token.lower) && !esIsNoun(token.lower)) ||
      (token.word &&
        /^\p{L}*[áéíóú]\p{L}*(?:me|te|se|lo|la|le|nos|os|los|las|les)$/u.test(token.lower) &&
        !esIsInfinitive(token.lower) &&
        !/(?:ándo|iéndo|yéndo)/u.test(token.lower))
        ? 1
        : 0) + esFiniteCount(at, j + 1);
}

// es.yaml rule es.diacritics def esVerbAhead
export function esVerbAhead(at: SpanishAround, k: number): boolean {
  const token = at.tokens[at.i + k];
  return k > 8 || !token || token.broken || /^[.;:!?,]$/u.test(token.text)
    ? false
    : /^(?:que|quien|quienes)$/u.test(token.lower)
      ? false
      : ES_DETERMINERS.has(token.lower) ||
          ES_PREPOSITIONS.has(token.lower) ||
          ES_CLITICS.has(token.lower)
        ? esVerbAhead(at, k + 1)
        : (token.word &&
            (ES_DIA_FINITE.has(token.lower) ||
              (esFiniteVerb(token.lower) && !esIsNoun(token.lower)))) ||
          esVerbAhead(at, k + 1);
}

// es.yaml rule es.diacritics def esMonoMi
export function esMonoMi(
  at: SpanishAround,
  prev: string,
  next: string,
  nextToken: SpanishToken | undefined,
  ends: boolean,
) {
  if (!ES_PREPOSITIONS.has(prev)) return null;
  const k = /^(?:más|menos|muy|tan|bastante)$/u.test(next) ? 2 : 1;
  const adjective = at.next(k);
  return /^(?:bemol|sostenido|mayor|menor)$/u.test(next)
    ? null
    : ends || /^(?:mismo|misma|me|que|no|el|la|los|las|lo)$/u.test(next)
      ? "mí"
      : next === "era" && (prev === "en" || prev === "de")
        ? null
        : next &&
            next !== "contra" &&
            !/^\p{Lu}/u.test(nextToken?.text ?? "") &&
            esNotNounPhrase(next)
          ? "mí"
          : esIsInfinitive(next) &&
              !esIsNoun(next) &&
              !/^(?:parecer|entender|ver)$/u.test(next) &&
              (prev === "a" || /^(?:eso|esto|aquello|nada|algo|tal)$/u.test(at.next(2)))
            ? "mí"
            : prev === "a" && /^(?:toca|respecta|concierne|atañe)$/u.test(next)
              ? "mí"
              : (next === "son" || (next === "era" && prev !== "en" && prev !== "de")) &&
                  (ES_DETERMINERS.has(at.next(2)) || !!esReadNoun(at.next(2))?.plural)
                ? "mí"
                : (esParticiple(adjective) ||
                      ES_INVARIANT.has(adjective) ||
                      /ibles?$/u.test(adjective) ||
                      (k === 2 && !!esAttributeOf(adjective))) &&
                    !ES_PRENOMINAL.has(adjective.replace(/s$/u, "")) &&
                    (at.endsAfter(k) || ES_PREPOSITIONS.has(at.next(k + 1)))
                  ? "mí"
                  : (next === "y" || next === "o" || next === "ni") &&
                      (ES_DIA_PRONOUNS.has(at.next(2)) || ES_PREPOSITIONS.has(at.next(2)))
                    ? "mí"
                    : null;
}

// es.yaml rule es.diacritics def esMonoTu
export function esMonoTu(at: SpanishAround, prev: string, next: string, ends: boolean) {
  return ES_CLITICS.has(next)
    ? "tú"
    : /^(?:solo|sola|más)$/u.test(next) && at.endsAfter(1)
      ? "tú"
      : /^(?:si|que|cuando|y|pero|porque|aunque)$/u.test(prev) &&
          /(?:as|es)$/u.test(next) &&
          esVerbLike(next) &&
          ES_DETERMINERS.has(at.next(2))
        ? "tú"
        : (next === "no" || ES_ONE_OFF.has(next)) && !esKnownNominal(at.next(2))
          ? "tú"
          : ends
            ? /^(?:como|entre|que|sino|según|excepto|menos|incluso|y|o|ni)$/u.test(prev)
              ? "tú"
              : null
            : next === "y" && ES_DIA_PRONOUNS.has(at.next(2)) && ES_PREPOSITIONS.has(prev)
              ? "tú"
              : esSecondPersonVerb(next)
                ? "tú"
                : null;
}

// es.yaml rule es.diacritics def esMonoStressed
export function esMonoStressed(at: SpanishAround, word: string, prev: string, next: string) {
  return word === "mí" &&
    (/^(?:bemol|sostenido)$/u.test(next) ||
      (/^(?:mayor|menor)$/u.test(next) && /^(?:en|de)$/u.test(prev) && at.endsAfter(1)))
    ? "mi"
    : esVerbLike(prev) || ES_DIA_FINITE.has(prev) || /^(?:como|que|entre)$/u.test(prev)
      ? null
      : word === "tú" && next.endsWith("s") && esFiniteVerb(next)
        ? null
        : esSolidNoun(next) && !/^(?:bemol|menor|mayor)$/u.test(next)
          ? word === "tú"
            ? "tu"
            : "mi"
          : null;
}

// es.yaml rule es.diacritics def esMonoEl
export function esMonoEl(
  at: SpanishAround,
  prev: string,
  next: string,
  nextToken: SpanishToken | undefined,
) {
  return /^[.,;:!?()]$/u.test(nextToken?.text ?? "") || (!nextToken && !at.starts)
    ? "él"
    : next === "cuando" && (at.endsAfter(1) || /^(?:sino|ni|y|o)$/u.test(at.next(2)))
      ? null
      : /^(?:pero|aunque|cuando|mientras|un|una|unos|unas)$/u.test(next)
        ? "él"
        : /ó$/u.test(next) && !esIsNoun(next)
          ? "él"
          : /^(?:mismo)$/u.test(next) &&
              (ES_COMMON_VERBS.has(at.next(2)) || ES_CLITICS.has(at.next(2)))
            ? "él"
            : next === "te" && (ES_TEA.has(at.next(2)) || at.endsAfter(1))
              ? null
              : ES_CLITICS.has(next) && next !== "la" && next !== "lo"
                ? "él"
                : (next === "la" || next === "lo") &&
                    esFiniteForm(at.next(2)) &&
                    !esIsNoun(at.next(2)) &&
                    !ES_PREPOSITIONS.has(at.next(2))
                  ? "él"
                  : ES_COMMON_VERBS.has(next) ||
                      (ES_ONE_OFF.has(next) && next !== "mismo" && next !== "misma")
                    ? "él"
                    : /a$/u.test(next) &&
                        !/^h?[aá]/u.test(next) &&
                        esFiniteForm(next) &&
                        esReadNoun(next)?.gender === "f" &&
                        !esReadNoun(next)?.plural &&
                        !esParticipleOf(next) &&
                        !esGenderedForm(next) &&
                        !at.starts
                      ? "él"
                      : ES_DIA_NUMBERS.has(next) &&
                          !!esReadNoun(at.next(2))?.plural &&
                          !/^(?:de|veces)$/u.test(at.next(2)) &&
                          !at.starts
                        ? "él"
                        : next === "no" &&
                            (ES_CLITICS.has(at.next(2)) ||
                              ES_COMMON_VERBS.has(at.next(2)) ||
                              ES_DIA_FINITE.has(at.next(2)) ||
                              /^(?:siempre|nunca|ya)$/u.test(at.next(2)))
                          ? "él"
                          : (next === "y" || next === "o") &&
                              ES_DIA_PRONOUNS.has(at.next(2)) &&
                              ES_PREPOSITIONS.has(prev)
                            ? "él"
                            : null;
}

// es.yaml rule es.diacritics def esMonoElAccent
export function esMonoElAccent(at: SpanishAround, prev: string, next: string) {
  const governed =
    /^(?:con|en|sin|sobre|entre|hacia|desde|hasta|tras|según|ante|bajo|contra|durante|mediante)$/u.test(
      prev,
    );
  if (!(at.starts || governed)) return null;
  const k = next === "mismo" ? 2 : 1;
  const noun = at.next(k);
  if (!(noun && !noun.endsWith("s") && !/^\p{Lu}/u.test(at.tokens[at.i + k].text))) return null;
  if (at.next(k + 1) === "y" && ES_DIA_PRONOUNS.has(at.next(k + 2))) return null;
  const form = esGenderedForm(noun);
  const masculineNoun =
    esSolidNoun(noun) ||
    (!!form &&
      esIsNoun(noun) &&
      !form.feminine &&
      !form.plural &&
      !esParticiple(noun) &&
      !ES_NOT_AFTER_EL.has(noun));
  const verbForm = esVerbLike(noun) || esFiniteVerb(noun);
  return masculineNoun &&
    esReadNoun(noun)?.gender !== "f" &&
    (!verbForm || /^(?:de|del)$/u.test(at.next(k + 1))) &&
    (k === 1 || esIsNoun(noun))
    ? "el"
    : null;
}

// es.yaml rule es.diacritics def esMonoSe
export function esMonoSe(at: SpanishAround, prev: string, next: string, ends: boolean) {
  return /[áéíóú]/u.test(next) && ES_ASKED_FORMS.has(next)
    ? "sé"
    : prev === "lo" || prev === "me"
      ? prev === "me" && /^(?:lo|la|los|las)$/u.test(next) && esSolidNoun(at.next(2))
        ? "sé"
        : /^(?:te|le|les|lo|la|los|las)$/u.test(next)
          ? null
          : "sé"
      : next === "de" && /^(?:qué|quién|quiénes|dónde|cuál|cuáles)$/u.test(at.next(2))
        ? "sé"
        : esPlainInfinitive(next) && !ES_PREPOSITIONS.has(prev) && prev !== "para"
          ? "sé"
          : at.starts &&
              /^\p{Lu}/u.test(at.tokens[at.i].text) &&
              (ES_INVARIANT.has(next) ||
                /(?:ble|nte|z)$/u.test(next) ||
                (!!esGenderedForm(next) && !esParticipleOf(next))) &&
              !esFiniteVerb(next) &&
              (at.endsAfter(1) || ES_PREPOSITIONS.has(at.next(2)))
            ? "sé"
            : !/^(?:no|yo|ya|tampoco|bien)$/u.test(prev)
              ? null
              : ends
                ? "sé"
                : /^(?:lo|la|los|las)$/u.test(next) &&
                    (esSolidNoun(at.next(2)) || at.next(2) === "que")
                  ? "sé"
                  : /^(?:si|qué|cómo|dónde|quién|quiénes|cuándo|cuál|cuánto|cuántos|nada|nadie|mucho|muy|poco|eso|esto|que|como|donde|quien|cuando|cual)$/u.test(
                        next,
                      )
                    ? "sé"
                    : null;
}

// es.yaml rule es.diacritics def esMonoDe
export function esMonoDe(at: SpanishAround, prev: string, next: string, ends: boolean) {
  return ends && prev
    ? "dé"
    : esGiveObject(at) && esSubjunctiveSlot(at)
      ? "dé"
      : /^(?:él|ella|usted|dios)$/u.test(prev) &&
          esSubjunctiveSlot(at) &&
          /^(?:el|la|los|las|un|una|este|esta|estos|estas|ese|esa|su|sus|tu|tus|mi|mis)$/u.test(
            next,
          )
        ? "dé"
        : /^(?:lo|la|los|las)$/u.test(prev) && /^(?:me|te|se|le|les|nos|os)$/u.test(at.prev(2))
          ? "dé"
          : !/^(?:me|te|le|les|nos|os)$/u.test(prev)
            ? null
            : ES_DETERMINERS.has(at.prev(2)) || ES_PREPOSITIONS.has(at.prev(2))
              ? null
              : esAround(at.tokens, at.i - 1).starts
                ? null
                : esIsInfinitive(next)
                  ? null
                  : "dé";
}

// es.yaml rule es.diacritics def esMonoSi
export function esMonoSi(
  at: SpanishAround,
  prev: string,
  next: string,
  nextToken: SpanishToken | undefined,
  ends: boolean,
) {
  const after = at.tokens[at.i + 2];
  const lead = /^(?:pues|ahora|entonces)$/u.test(prev) || (prev === "vez" && at.prev(2) === "esta");
  return prev === "el" || prev === "un"
    ? next && esIsNoun(next)
      ? null
      : "sí"
    : next === "que" && !at.endsAfter(1) && prev !== "como"
      ? "sí"
      : prev === "en" && (next === "de" || ends)
        ? "sí"
        : nextToken?.text === "," && at.starts && ES_ANSWER_AFTER.has(at.next(2))
          ? "sí"
          : next === "pero" && at.starts
            ? "sí"
            : nextToken?.text === "," &&
                at.tokens[at.i - 1]?.text === "," &&
                after &&
                !after.broken &&
                (/^[¿¡]$/u.test(after.text) || /^(?:pero|claro|aunque)$/u.test(after.lower))
              ? "sí"
              : nextToken?.text === ","
                ? ES_PLAIN_SI_PREV.has(prev)
                  ? "sí"
                  : null
                : prev === "pero" &&
                    esDeniedBefore(at, at.i - 2, Math.max(0, at.i - 16)) &&
                    esPlainSentence(at, at.i + 1) &&
                    esFiniteCount(at, at.i + 1) === 1
                  ? "sí"
                  : /^(?:esto|eso|aquello)$/u.test(prev) &&
                      esAround(at.tokens, at.i - 1).starts &&
                      /^(?:es|era|fue|será|sería|está|estaba)$/u.test(next) &&
                      esEndsPlainly(at, 2, 7)
                    ? "sí"
                    : prev === "pero" &&
                        /^(?:a|al|un|una|unos|unas)$/u.test(next) &&
                        !esVerbAhead(at, 1)
                      ? "sí"
                      : /^[»”"]$/u.test(nextToken?.text ?? "") &&
                          /^[«“"]$/u.test(at.tokens[at.i - 1]?.text ?? "") &&
                          at.tokens[at.i + 2]?.text === ","
                        ? "sí"
                        : (lead || at.starts) &&
                            esPastFact(at, !lead) &&
                            esPlainSentence(at, at.i + 1)
                          ? "sí"
                          : ends
                            ? "sí"
                            : null;
}

// es.yaml rule es.diacritics def esMonoAun
export function esMonoAun(at: SpanishAround, prev: string, next: string, ends: boolean) {
  return next === "no" && !esIsGerund(at.next(2))
    ? "aún"
    : /^(?:más|menos|mayor|menor|mejor|peor)$/u.test(next)
      ? "aún"
      : /^(?:más|menos)$/u.test(prev)
        ? "aún"
        : ES_CLITICS.has(next) && next !== "la" && next !== "las" && next !== "los"
          ? "aún"
          : esIsGerund(next) && /^est[aá]/u.test(prev)
            ? "aún"
            : /^(?:así|cuando|si|con|sin|a|al|en)$/u.test(next) || ES_CONJUNCTIONS.has(next)
              ? null
              : esFiniteForm(next) &&
                  !esParticiple(next) &&
                  (!esAttributeOf(next) || esIsNoun(next)) &&
                  (!esIsNoun(next) || (/[oae]$/u.test(next) && at.tokens[at.i + 2]?.text !== ","))
                ? "aún"
                : esSubjunctiveLike(next) &&
                    !esIsNoun(next) &&
                    !esAttributeOf(next) &&
                    [1, 2, 3].some((k) => at.prev(k) === "que")
                  ? "aún"
                  : !at.starts && esParticipleOf(next) && at.tokens[at.i + 2]?.text !== ","
                    ? "aún"
                    : ends && !at.starts
                      ? "aún"
                      : null;
}

// es.yaml rule es.diacritics def esMonoAunAccent
export function esMonoAunAccent(at: SpanishAround, prev: string, next: string) {
  return prev === "ni"
    ? "aun"
    : /^(?:más|menos|mejor|peor|mayor|menor)$/u.test(prev) || /mente$/u.test(prev)
      ? null
      : next === "si" || next === "cuando" || (esIsGerund(next) && !/^est[aá]/u.test(prev))
        ? "aun"
        : next === "no" && esIsGerund(at.next(2))
          ? "aun"
          : at.starts && (ES_PREPOSITIONS.has(next) || esParticipleOf(next)) && esConcessive(at, 1)
            ? "aun"
            : next === "así" &&
                (at.tokens[at.i + 2]?.text === "," ||
                  ((at.starts || /^(?:y|e|pero|mas|sino)$/u.test(prev)) &&
                    !!at.next(2) &&
                    !/^(?:de|que)$/u.test(at.next(2))))
              ? "aun"
              : null;
}

// es.yaml rule es.diacritics def esMonoMas
export function esMonoMas(
  at: SpanishAround,
  prev: string,
  next: string,
  nextToken: SpanishToken | undefined,
  ends: boolean,
) {
  return at.starts || at.tokens[at.i - 1]?.text === ","
    ? null
    : /^\p{Lu}/u.test(at.tokens[at.i].text)
      ? null
      : ES_DETERMINERS.has(prev) || prev === "lo"
        ? "más"
        : ends || /^(?:que|de|tarde|temprano|bien|mal|o|allá|adelante|grande|pequeño)$/u.test(next)
          ? "más"
          : /^\p{N}/u.test(nextToken?.text ?? "") || !!esAttributeOf(next)
            ? "más"
            : null;
}

// es.yaml rule es.diacritics def esMonosyllable
export function esMonosyllable(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const prev = at.prev();
  const next = at.next();
  const nextToken = at.tokens[at.i + 1];
  const ends =
    (nextToken ? /^[.,;:!?)]$/u.test(nextToken.text) && !nextToken.broken : true) &&
    !(nextToken?.text === "." && at.tokens[at.i + 2]?.text === ".");
  return word === "mi"
    ? esMonoMi(at, prev, next, nextToken, ends)
    : word === "tu"
      ? esMonoTu(at, prev, next, ends)
      : word === "tú" || word === "mí"
        ? esMonoStressed(at, word, prev, next)
        : word === "el"
          ? esMonoEl(at, prev, next, nextToken)
          : word === "él"
            ? esMonoElAccent(at, prev, next)
            : word === "se"
              ? esMonoSe(at, prev, next, ends)
              : word === "de"
                ? esMonoDe(at, prev, next, ends)
                : word === "té"
                  ? /^(?:se|me|no)$/u.test(prev) && !!next && !ES_TEA.has(next)
                    ? "te"
                    : null
                  : word === "te"
                    ? prev === "un" || prev === "una"
                      ? "té"
                      : (prev === "de" || prev === "con") &&
                          (ends || next === "y" || next === "ahora")
                        ? "té"
                        : (prev === "el" || prev === "del" || prev === "al") &&
                            (ends || ES_TEA.has(next))
                          ? "té"
                          : null
                    : word === "si"
                      ? esMonoSi(at, prev, next, nextToken, ends)
                      : word === "aun"
                        ? esMonoAun(at, prev, next, ends)
                        : word === "aún"
                          ? esMonoAunAccent(at, prev, next)
                          : word === "mas"
                            ? esMonoMas(at, prev, next, nextToken, ends)
                            : null;
}

// es.yaml rule es.verbAccents def ES_DEMONSTRATIVE_FORM
export const ES_DEMONSTRATIVE_FORM = {
  este: { feminine: false, plural: false },
  estos: { feminine: false, plural: true },
  ese: { feminine: false, plural: false },
  esos: { feminine: false, plural: true },
  aquel: { feminine: false, plural: false },
  aquellos: { feminine: false, plural: true },
  esta: { feminine: true, plural: false },
  estas: { feminine: true, plural: true },
  esa: { feminine: true, plural: false },
  esas: { feminine: true, plural: true },
  aquella: { feminine: true, plural: false },
  aquellas: { feminine: true, plural: true },
} as Readonly<Record<string, { feminine: boolean; plural: boolean }>>;

// es.yaml rule es.verbAccents def ES_PLAIN_TWINS
export const ES_PLAIN_TWINS = new Map([
  ["sera", "será"],
  ["seras", "serás"],
  ["serian", "serían"],
  ["veras", "verás"],
  ["venia", "venía"],
]);

// es.yaml rule es.verbAccents def ES_HIATUS_NOUNS
export const ES_HIATUS_NOUNS = new Map([
  ["lio", "lío"],
  ["rio", "río"],
  ["frio", "frío"],
]);

// es.yaml rule es.verbAccents def esPostponedAdjective
export function esPostponedAdjective(at: SpanishAround, accented: string) {
  const ending = /(o|a)(s?)$/u.exec(accented);
  const noun = ending && esReadNoun(at.prev());
  if (!(ending && noun?.gender && !at.tokens[at.i - 1].broken)) return false;
  if ((noun.gender === "f") !== (ending[1] === "a") || noun.plural !== (ending[2] === "s"))
    return false;
  const before = at.prev(2);
  const article = /^(?:un|una|unos|unas)$/u.test(before);
  const preposition = ES_PREPOSITIONS.has(before)
    ? 2
    : ES_DETERMINERS.has(before) && ES_PREPOSITIONS.has(at.prev(3))
      ? 3
      : 0;
  const after0 = at.next();
  const governed =
    article ||
    preposition > 0 ||
    (!!before && esFiniteVerb(before) && !esIsNoun(before) && !esReadNoun(before)) ||
    (ES_DETERMINERS.has(before) &&
      !!after0 &&
      esFiniteVerb(after0) &&
      !esIsNoun(after0) &&
      !esAttribute(after0) &&
      !ES_CLITICS.has(after0) &&
      !ES_PREPOSITIONS.has(after0) &&
      !ES_CONJUNCTIONS.has(after0)) ||
    (ES_DETERMINERS.has(before) && /(?:o|as|os)$/u.test(at.tokens[at.i].lower));
  if (!governed) return false;
  const after = at.next();
  return !article && preposition && esAround(at.tokens, at.i - preposition).starts
    ? at.endsAfter()
    : at.endsAfter() ||
        ((after === "y" || after === "e") && !ES_DETERMINERS.has(at.next(2))) ||
        (ES_PREPOSITIONS.has(after) && after !== "a") ||
        /^\p{L}{4,}mente$/u.test(after);
}

// es.yaml rule es.verbAccents def esFormOf
export function esFormOf(word: string) {
  const m = /(o|a)(s?)$/u.exec(word);
  return m ? { feminine: m[1] === "a", plural: m[2] === "s" } : null;
}

// es.yaml rule es.verbAccents def esAgrees
export function esAgrees(form: { feminine: boolean | null; plural: boolean }, accented: string) {
  const own = esFormOf(accented);
  return (
    !!own &&
    own.plural === form.plural &&
    (form.feminine === null || own.feminine === form.feminine)
  );
}

// es.yaml rule es.verbAccents def esAgreesWithArticle
export function esAgreesWithArticle(article: string, accented: string) {
  return esAgrees({ feminine: !article.startsWith("lo"), plural: article.endsWith("s") }, accented);
}

// es.yaml rule es.verbAccents def esAgreesWithNext
export function esAgreesWithNext(at: SpanishAround, accented: string) {
  const own = esFormOf(accented);
  const noun = esReadNoun(at.next());
  if (!(own && noun && !noun.paired && noun.gender && !at.tokens[at.i + 1].broken)) return false;
  if (esFiniteVerb(at.next()) || noun.plural !== own.plural) return false;
  return (noun.gender === "f") === own.feminine;
}

// es.yaml rule es.verbAccents def esPerfectParticipleLike
export function esPerfectParticipleLike(word: string) {
  return /(?:ado|ido)$/u.test(word) && !!esParticiple(word);
}

// es.yaml rule es.verbAccents def esVaVerbless
export function esVaVerbless(at: SpanishAround, k: number): boolean {
  const word = at.next(k);
  return k > 8
    ? false
    : at.endsAfter(k - 1) || !word
      ? true
      : /^(?:es|son|era|fue|está|están|hay|ha|han|ve|va|da|dio|vio|hace|tiene|puede|dice)$/u.test(
            word,
          )
        ? false
        : ES_PREPOSITIONS.has(word) || ES_DETERMINERS.has(word) || ES_CONJUNCTIONS.has(word)
          ? esVaVerbless(at, k + 1)
          : esFiniteVerb(word) && !esIsNoun(word) && !esAttribute(word) && !esGenderedForm(word)
            ? false
            : esVaVerbless(at, k + 1);
}

// es.yaml rule es.verbAccents def esNominalAfterArticle
export function esNominalAfterArticle(
  at: SpanishAround,
  accented: string,
  prev: string,
  next: string,
) {
  const before = at.prev(2);
  const opens = !!at.tokens[at.i - 1] && esAround(at.tokens, at.i - 1).starts;
  return prev !== "los" && /os?$/u.test(accented)
    ? null
    : ES_PREPOSITIONS.has(before) ||
        (ES_SER.has(before) && esAgreesWithArticle(prev, accented)) ||
        (opens && next === "que" && esAgreesWithArticle(prev, accented)) ||
        esIsInfinitive(before) ||
        (at.tokens[at.i - 1] &&
          esAround(at.tokens, at.i - 1).starts &&
          /^(?:de|del|no)$/u.test(next) &&
          esAgreesWithArticle(prev, accented)) ||
        /(?:ado|ido)$/u.test(before) ||
        (!!before &&
          (next === "de" || next === "del") &&
          !ES_NOT_BEFORE_ARTICLE.has(before) &&
          !/^\p{Lu}/u.test(at.tokens[at.i - 2].text)) ||
        (!!before && esFiniteVerb(before) && !esIsNoun(before) && !ES_CLITICS.has(at.prev(3))) ||
        (!!next &&
          esFiniteVerb(next) &&
          !esIsNoun(next) &&
          !esAttribute(next) &&
          !ES_CLITICS.has(next) &&
          !ES_PREPOSITIONS.has(next) &&
          !ES_CONJUNCTIONS.has(next) &&
          !ES_DETERMINERS.has(next))
      ? accented
      : null;
}

// es.yaml rule es.verbAccents def esNominal
export function esNominal(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const accented = ES_ACCENTED_NOMINAL.get(word);
  if (!accented) return null;
  const prev = at.prev();
  const next = at.next();
  const count = at.tokens[at.i - 1];
  const adjective = esGenderedForm(prev);
  const numbered = /^\p{N}/u.test(at.tokens[at.i + 1]?.text ?? "") && !at.tokens[at.i + 1].broken;
  const opener =
    at.starts ||
    (/^(?:la|las|los)$/u.test(prev) && at.tokens[at.i - 1] && esAround(at.tokens, at.i - 1).starts);
  const between = ES_PRENOMINAL.has(prev.replace(/s$/u, ""))
    ? (esFormOf(prev) ?? { feminine: null, plural: prev.endsWith("s") })
    : null;
  return /^(?:una|unas|mis|tus|sus|toda|otra|otras|muchas|pocas|varias|nuestra|nuestras)$/u.test(
    prev,
  ) && /os?$/u.test(accented)
    ? null
    : ES_VA_DETERMINERS.has(prev) || ES_VA_DEGREE.has(prev) || ES_SER.has(prev)
      ? accented
      : /^cuy[oa]s?$/u.test(next) || ES_VA_TENER.has(prev)
        ? accented
        : /^\p{L}{3,}mente$/u.test(prev) &&
            (ES_DETERMINERS.has(at.prev(2)) || /^(?:del|al)$/u.test(at.prev(2))) &&
            (esAgreesWithNext(at, accented) ||
              (!esFormOf(accented) && !!esReadNoun(next) && !esFiniteVerb(next)))
          ? accented
          : prev === "lo" && next === "que" && /o$/u.test(accented)
            ? accented
            : prev === "tu" && !word.endsWith("s")
              ? accented
              : count &&
                  !at.tokens[at.i].broken &&
                  /^\p{N}{1,3}$/u.test(count.text) &&
                  count.text !== "1" &&
                  accented.endsWith("s")
                ? accented
                : ES_VA_DEMONSTRATIVES.has(prev) &&
                    ((esFiniteVerb(at.prev(2)) && !esIsNoun(at.prev(2))) ||
                      esIsInfinitive(at.prev(2))) &&
                    esAgrees(ES_DEMONSTRATIVE_FORM[prev], accented)
                  ? accented
                  : adjective &&
                      !esFiniteVerb(prev) &&
                      !esIsNoun(prev) &&
                      ES_VA_DETERMINERS.has(at.prev(2)) &&
                      adjective.plural === accented.endsWith("s") &&
                      (!esFormOf(accented) || esFormOf(accented)!.feminine === adjective.feminine)
                    ? accented
                    : numbered && (at.starts || /^(?:la|las|los)$/u.test(prev))
                      ? accented
                      : opener &&
                          esVaVerbless(at, 1) &&
                          ((/^(?:la|las|los)$/u.test(prev) &&
                            at.endsAfter() &&
                            esAgreesWithArticle(prev, accented)) ||
                            (at.starts &&
                              (((next === "de" || next === "del") &&
                                at.endsAfter(2) &&
                                !!at.next(2) &&
                                !esIsInfinitive(at.next(2)) &&
                                !ES_VA_TIME.has(at.next(2))) ||
                                esAgreesWithNext(at, accented))))
                        ? accented
                        : ES_VA_DEMONSTRATIVES.has(prev) && ES_PREPOSITIONS.has(at.prev(2))
                          ? accented
                          : /^(?:hay|había|habrá|hubo|haya|habría)$/u.test(prev)
                            ? accented
                            : /^(?:la|las|tu|tus|esta|estas|esa|esas|aquella|aquellas)$/u.test(
                                  prev,
                                ) && esAgreesWithNext(at, accented)
                              ? accented
                              : /^(?:buen|gran|primer|tercer|algún|ningún)$/u.test(prev) &&
                                  (prev === "gran" || /o$/u.test(accented))
                                ? accented
                                : between &&
                                    (ES_VA_DETERMINERS.has(at.prev(2)) ||
                                      /^(?:la|las|los|el)$/u.test(at.prev(2))) &&
                                    esAgrees(between, accented)
                                  ? accented
                                  : esIsInfinitive(prev) &&
                                      at.prev(2) &&
                                      !ES_PREPOSITIONS.has(at.prev(2)) &&
                                      ES_PREPOSITIONS.has(next)
                                    ? accented
                                    : /^(?:la|las|los)$/u.test(prev)
                                      ? esNominalAfterArticle(at, accented, prev, next)
                                      : esPostponedAdjective(at, accented)
                                        ? accented
                                        : ES_PREPOSITIONS.has(prev) && prev !== "a"
                                          ? accented
                                          : null;
}

// es.yaml rule es.verbAccents def esNotName
export function esNotName(word: string) {
  return (
    !ES_GIVEN_NAMES.has(word) &&
    (ES_CLITICS.has(word) ||
      ES_PREPOSITIONS.has(word) ||
      ES_CONJUNCTIONS.has(word) ||
      ES_DETERMINERS.has(word) ||
      ES_VA_CLOSED.has(word) ||
      /mente$/u.test(word) ||
      !!esAttribute(word) ||
      esIsInfinitive(word) ||
      esFiniteVerb(word))
  );
}

// es.yaml rule es.verbAccents def esOpensAt
export function esOpensAt(at: SpanishAround, k: number) {
  const before = esAround(at.tokens, at.i - k);
  return before.starts || /^(?:y|e|pero|que|cuando|porque|pues|aunque)$/u.test(before.prev());
}

// es.yaml rule es.verbAccents def esNamesEnd
export function esNamesEnd(at: SpanishAround, k: number, last: number): number {
  return k < last &&
    at.tokens[at.i - k]?.word &&
    /^\p{Lu}\p{Ll}/u.test(at.tokens[at.i - k].text) &&
    !esNotName(at.tokens[at.i - k].lower) &&
    at.prev(k)
    ? esNamesEnd(at, k + 1, last)
    : k;
}

// es.yaml rule es.verbAccents def esNounSubject
export function esNounSubject(at: SpanishAround) {
  if ([1, 2, 3].some((n) => at.next(n) === "yo")) return false;
  const k = ES_VA_ADVERBS.has(at.prev()) ? 2 : 1;
  const end = esNamesEnd(at, k, k + 3);
  const noun = at.prev(k);
  const det = at.prev(k + 1);
  return end > k
    ? esOpensAt(at, end - 1)
    : !!noun &&
        ES_VA_SUBJECT_DETERMINERS.has(det) &&
        !ES_VA_TIME.has(noun) &&
        (esIsNoun(noun) || !!esAttribute(noun)) &&
        !noun.endsWith("s") &&
        esOpensAt(at, k + 1) &&
        (ES_AFTER_VERB.has(at.next()) || at.next() === "a" || at.next() === "al");
}

// es.yaml rule es.verbAccents def esVaPreterite
export function esVaPreterite(at: SpanishAround, word: string, prev: string) {
  const pronounSubject =
    (ES_VA_SUBJECTS.has(prev) && esOpensAt(at, 1)) ||
    (ES_VA_SUBJECTS.has(at.prev(2)) &&
      /^(?:no|le|les|lo|la|me|te|nos)$/u.test(prev) &&
      esOpensAt(at, 2)) ||
    (ES_VA_SUBJECTS.has(at.prev(3)) &&
      at.prev(2) === "no" &&
      /^(?:le|les|lo|la|me|te|nos|se)$/u.test(prev) &&
      esOpensAt(at, 3));
  const named =
    !pronounSubject &&
    /o$/u.test(word) &&
    !esParticiple(word) &&
    (!ES_ACCENTED_NOMINAL.has(word) || ES_VA_ARTICLES.has(at.next())) &&
    at.tokens[at.i + 1]?.text !== "-" &&
    (!(esIsNoun(word) || esAttribute(word)) ||
      ES_AFTER_VERB.has(at.next()) ||
      (at.next() === "a" &&
        !esIsInfinitive(at.next(2)) &&
        !/^(?:junto|debido|respecto)$/u.test(word))) &&
    esNounSubject(at);
  const subject = pronounSubject || named;
  if (!((prev === "se" && at.prev(2) !== "per") || subject)) return null;
  const m = /^(\p{L}{2,})o$/u.exec(word);
  const aside =
    ES_VA_FUNCTION_WORDS.has(word) ||
    (subject && /^(?:creo|pienso|supongo|digo|imagino|opino)$/u.test(word));
  const nounReading =
    pronounSubject &&
    (esIsNoun(word) || esAttribute(word)) &&
    !ES_AFTER_VERB.has(at.next()) &&
    !/^(?:varias|varios|muchas|muchos|dos|tres|cuatro|cinco|algunas|algunos)$/u.test(at.next());
  if (!(m && word.length > 3 && !aside && !nounReading)) return null;
  return esIsVerb(`${m[1]}ar`)
    ? `${m[1]}ó`
    : (esIsVerb(`${m[1]}er`) || esIsVerb(`${m[1]}ir`)) && !esIsNoun(word)
      ? `${m[1]}ió`
      : null;
}

// es.yaml rule es.verbAccents def esVaCliticPreterite
export function esVaCliticPreterite(at: SpanishAround, word: string, prev: string) {
  const plainStem = /^(\p{L}{3,})o$/u.exec(word);
  if (!(
    plainStem &&
    ES_CLITICS.has(prev) &&
    esIsVerb(`${plainStem[1]}ar`) &&
    !esFiniteVerb(word) &&
    !esNounForm(word) &&
    !esIsNoun(word) &&
    (!esAttribute(word) || !/^(?:lo|la|los|las)$/u.test(prev) || ES_CLITICS.has(at.prev(2)))
  ))
    return null;
  return `${plainStem[1]}ó`;
}

// es.yaml rule es.verbAccents def esVaImperfect
export function esVaImperfect(at: SpanishAround, word: string, prev: string) {
  if (!ES_VA_BEFORE_VERB.has(prev)) return null;
  const m = /^(\p{L}+)ia(s|n|mos)?$/u.exec(word);
  const direction =
    word === "hacia" &&
    /^(?:abajo|arriba|adelante|atrás|afuera|adentro|allá|acá|aquí|allí|delante|el|la|los|las)$/u.test(
      at.next(),
    );
  if (!(
    !direction &&
    m &&
    (esIsVerb(`${m[1]}er`) || esIsVerb(`${m[1]}ir`) || esIsInfinitive(m[1]))
  ))
    return null;
  return `${m[1]}ía${m[2] ?? ""}`;
}

// es.yaml rule es.verbAccents def esVaStressed
export function esVaStressed(at: SpanishAround, word: string, prev: string) {
  const governed = ES_VA_SUBJECTS.has(prev) && ES_PREPOSITIONS.has(at.prev(2));
  if (!(!governed && (ES_VA_BEFORE_VERB.has(prev) || /^(?:ya|tú|que|si|quién)$/u.test(prev))))
    return null;
  const stressed = /^(\p{L}+)([ui])(a|as|an|e|es|en)$/u.exec(word);
  const iar =
    stressed?.[2] === "i" &&
    /^(?:ampl|env|conf|f|var|cr|gu|enfr|desv|vac|esp|desaf|exp|resfr|hast|roc)$/u.test(stressed[1]);
  const uar = stressed?.[2] === "u" && !/[gc]$/u.test(stressed[1]);
  const future = /^(\p{L}*?[eií]r)(a|as|an|e)$/u.exec(word);
  return stressed && (iar || uar) && esIsVerb(`${stressed[1]}${stressed[2]}ar`) && !esIsNoun(word)
    ? `${stressed[1]}${stressed[2] === "u" ? "ú" : "í"}${stressed[3]}`
    : future &&
        (esIsInfinitive(future[1]) || future[1] === "ir") &&
        (!esIsNoun(word) || /^(?:ya|tú|se|me|te|le|lo|no)$/u.test(prev)) &&
        word !== "para"
      ? `${future[1]}${ES_FUTURE_ACCENTS[future[2]]}`
      : null;
}

// es.yaml rule es.verbAccents def esVaCliticsBack
export function esVaCliticsBack(at: SpanishAround, k: number): number {
  return k < 3 && /^(?:me|te|lo|la|los|las|le|les|nos|os)$/u.test(at.prev(k))
    ? esVaCliticsBack(at, k + 1)
    : k;
}

// es.yaml rule es.verbAccents def esVaFirstPreterite
export function esVaFirstPreterite(at: SpanishAround, word: string) {
  if (!(
    /^\p{L}{3,}e$/u.test(word) &&
    esSubjunctiveLike(word) &&
    !esIsNoun(word) &&
    !esAttribute(word)
  ))
    return null;
  const k = esVaCliticsBack(at, 1);
  const lead = at.prev(k);
  const leadStarts = esAround(at.tokens, at.i - k).starts;
  const clitics = k > 1 && esAround(at.tokens, at.i - k + 1).starts;
  const pastAfter = [1, 2, 3].some(
    (n) =>
      /^(?:ayer|anoche|anteayer)$/u.test(at.next(n)) ||
      (/^(?:pasado|pasada)$/u.test(at.next(n)) &&
        /^(?:semana|año|mes|lunes|martes|miércoles|jueves|viernes|sábado|domingo|verano|invierno)$/u.test(
          at.next(n - 1),
        )),
  );
  if (!(
    (leadStarts && /^(?:yo|ayer|anoche|anteayer)$/u.test(lead)) ||
    (k > 1 &&
      lead !== "que" &&
      (/^(?:ayer|anoche|anteayer)$/u.test(lead) || pastAfter) &&
      !ES_VA_DETERMINERS.has(at.prev(k + 1))) ||
    (clitics &&
      at.prev(k - 1) === "me" &&
      (at.endsAfter() || /^(?:a|en|de|con|sin|por)$/u.test(at.next())))
  ))
    return null;
  return `${word.slice(0, -1)}é`;
}

// es.yaml rule es.verbAccents def esVaFuture
export function esVaFuture(at: SpanishAround, word: string, prev: string) {
  const ira = /^ir(a|as|an)$/u.exec(word);
  const arFuture = /^(\p{L}+ar)(a|as|an)$/u.exec(word);
  return ira &&
    !ES_DETERMINERS.has(prev) &&
    !ES_PREPOSITIONS.has(prev) &&
    !/^(?:mi|tu|su|sus|nuestra|vuestra)$/u.test(prev) &&
    (esIsGerund(at.next()) || (esPerfectParticipleLike(at.next()) && !ES_CONJUNCTIONS.has(prev)))
    ? `ir${ES_FUTURE_ACCENTS[ira[1]]}`
    : arFuture &&
        esIsVerb(arFuture[1]) &&
        !esIsNoun(word) &&
        ![1, 2, 3].some((k) => ES_FUTURE_BLOCKERS.has(at.prev(k))) &&
        ((/^(?:cuándo|cuánto|cuánta|cuántos|cuántas|dónde|adónde)$/u.test(prev) &&
          at.tokens[at.i - 2]?.text === "¿") ||
          at.next() === "mañana")
      ? `${arFuture[1]}${ES_FUTURE_ACCENTS[arFuture[2]]}`
      : null;
}

// es.yaml rule es.verbAccents def esVerbAccent
export function esVerbAccent(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const prev = at.prev();
  return (
    esVaPreterite(at, word, prev) ??
    esVaCliticPreterite(at, word, prev) ??
    esVaImperfect(at, word, prev) ??
    esVaStressed(at, word, prev) ??
    esVaFirstPreterite(at, word) ??
    esVaFuture(at, word, prev)
  );
}

// es.yaml rule es.verbAccents def esHaciaTime
export function esHaciaTime(at: SpanishAround, j: number, n: number, start: number): boolean {
  if (!(j < at.tokens.length && n < 7)) return false;
  const token = at.tokens[j];
  return token.broken || /^[.;:!?]$/u.test(token.text)
    ? false
    : ES_VA_TIME_NOUNS.has(token.lower) ||
        (token.lower === "que" && j === at.i + start + 1) ||
        esHaciaTime(at, j + 1, n + 1, start);
}

// es.yaml rule es.verbAccents def esHacia
export function esHacia(at: SpanishAround) {
  const lower = at.tokens[at.i].lower;
  const prev = at.prev();
  const next = at.next();
  const numeral = /^\p{N}/u.test(at.tokens[at.i + 1]?.text ?? "");
  const start = next === "ya" ? 2 : 1;
  const amount = at.next(start);
  return lower === "hacía"
    ? (ES_DIRECTIONS.has(next) || ES_DETERMINERS.has(next)) &&
      esFiniteVerb(prev) &&
      !esIsNoun(prev) &&
      !esAttribute(prev) &&
      !ES_CLITICS.has(prev)
      ? "hacia"
      : null
    : lower !== "hacia"
      ? null
      : next === "las" && at.next(2) === "veces"
        ? "hacía"
        : ES_DIRECTIONS.has(next) || numeral
          ? null
          : ES_OBJECT_CLITICS.has(prev)
            ? "hacía"
            : ES_DETERMINERS.has(next)
              ? null
              : (prev === "qué" || (prev === "que" && at.prev(2) === "lo")) &&
                  !/^(?:más|ya)$/u.test(next)
                ? "hacía"
                : ES_WEATHER.has(next) || (next === "las" && at.next(2) === "veces")
                  ? "hacía"
                  : (ES_VA_AMOUNTS.has(amount) || ES_VA_NUMBERS.has(amount)) &&
                      esHaciaTime(at, at.i + start, 0, start)
                    ? "hacía"
                    : null;
}

// es.yaml rule es.verbAccents def esSeria
export function esSeria(at: SpanishAround) {
  if (!(at.tokens[at.i].lower === "seria")) return null;
  const prev = at.prev();
  if (ES_DEGREE_BEFORE.has(prev) || ES_LINKS.has(prev) || ES_DETERMINERS.has(prev)) return null;
  const k = /^(?:más|menos|muy|tan|mucho|bastante)$/u.test(at.next(1)) ? 2 : 1;
  const next = at.next(k);
  const form = esGenderedForm(next) ?? esParticiple(next);
  return next === "yo" || next === "mejor" || next === "peor"
    ? "sería"
    : !next || ES_VA_LEADING.has(next)
      ? null
      : form
        ? form.plural
          ? null
          : "sería"
        : k === 2 && (esIsNoun(next) || esIsInvariantEntry(next))
          ? "sería"
          : null;
}

// es.yaml rule es.verbAccents def esPlainTwin
export function esPlainTwin(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const fix = ES_PLAIN_TWINS.get(word);
  if (!fix) return null;
  if (!(at.starts || ES_SUBJECT_OR_NO.has(at.prev()))) return null;
  const next = at.next();
  return word === "veras"
    ? ES_VERAS_NEXT.has(next)
      ? fix
      : null
    : word === "venia"
      ? /^(?:de|a|desde|con|por)$/u.test(next)
        ? fix
        : null
      : next
        ? fix
        : null;
}

// es.yaml rule es.verbAccents def esHiatusNoun
export function esHiatusNoun(at: SpanishAround) {
  const fix = ES_HIATUS_NOUNS.get(at.tokens[at.i].lower);
  const prev = at.prev();
  return at.tokens[at.i].text === "Rio" &&
    at.next() === "de" &&
    /^\p{Lu}/u.test(at.tokens[at.i + 2]?.text ?? "")
    ? fix
    : fix && (ES_DETERMINERS.has(prev) || ES_BEFORE_HIATUS_NOUN.has(prev))
      ? fix
      : null;
}

// es.yaml rule es.verbAccents def esInItself
export function esInItself(at: SpanishAround) {
  if (!(at.tokens[at.i].lower === "si" && at.prev() === "en")) return null;
  const head = at.prev(2);
  if (!esIsNoun(head) || esFiniteVerb(head) || esIsInfinitive(head)) return null;
  const next = at.next();
  return at.endsAfter() || (esFiniteVerb(next) && !esIsNoun(next)) || ES_SER.has(next)
    ? "sí"
    : null;
}

// es.yaml rule es.paraQueAccent def ES_PAST_SUBJUNCTIVE
export const ES_PAST_SUBJUNCTIVE = /(?:ra|ras|ra|ramos|rais|ran|se|ses|semos|seis|sen)$/u;

// es.yaml rule es.paraQueAccent def ES_PRESENT_INDICATIVE
export const ES_PRESENT_INDICATIVE = /(?:o|as|a|amos|áis|an|es|e|emos|éis|en|imos|ís)$/u;

// es.yaml rule es.paraQueAccent def esParaQue
export function esParaQue(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  if (!(tokens[i].lower === "que" && at.prev() === "para" && tokens[i].text === "que")) return null;
  const k = esSkipClitics(at, 1, 3);
  const verb = at.next(k);
  if (!(verb && !/^\p{Lu}/u.test(tokens[i + k].text) && !ES_PAST_SUBJUNCTIVE.test(verb)))
    return null;
  if (!(ES_PRESENT_INDICATIVE.test(verb) && !esSubjunctiveLike(verb) && esFiniteVerb(verb)))
    return null;
  if (
    esIsNoun(verb) ||
    esParticiple(verb) ||
    /^(?:como|cuando|donde|mientras|halla|hallas|hallan)$/u.test(verb)
  )
    return null;
  const a = /^(\p{L}+?)(?:a|as|an|amos|áis)$/u.exec(verb);
  if (a && (esIsVerb(`${a[1]}er`) || esIsVerb(`${a[1]}ir`))) return null;
  return esReplaceToken(
    ctx,
    tokens[i],
    ["qué"],
    "spanishAccents",
    "review_msg_spanish_interrogative",
    tokens[i + k],
  );
}

// es.yaml rule es.paraQueAccent def esFramedAccent
export function esFramedAccent(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  const word = tokens[i].lower;
  const prev = at.prev();
  const fix =
    word === "ingles" &&
    (ES_BEFORE_LANGUAGE.has(prev) || (prev === "de" && ES_LANGUAGE_NOUNS.has(at.prev(2))))
      ? "inglés"
      : tokens[i].text === "Paris" &&
          /^(?:a|en|hacia|desde|hasta|para|por)$/u.test(prev) &&
          !/^\p{Lu}/u.test(tokens[i + 1]?.text ?? "")
        ? "París"
        : word === "seria" &&
            (/^(?:cuál|qué|quién|cómo|dónde)$/u.test(prev) ||
              (ES_AFTER_SERIA.has(at.next()) && at.next(2) !== "que"))
          ? "sería"
          : null;
  if (!fix) return null;
  return esReplaceToken(
    ctx,
    tokens[i],
    [fix],
    "spanishAccents",
    "review_msg_spanish_accent",
    tokens[i - 1],
  );
}

// es.yaml rule es.confusions def ES_PERFECT_BEFORE
export const ES_PERFECT_BEFORE =
  /^(?:pod\p{L}*|deb\p{L}*|pued\p{L}*|pud\p{L}*|tenía|tendría|que|sin|de|por|para|parece|parecía|habría)$/u;

// es.yaml rule es.confusions def esIsCount
export function esIsCount(token: SpanishToken | undefined) {
  return !!token && (/^\p{N}/u.test(token.text) || ES_CONFUSION_NUMBERS.has(token.lower));
}

// es.yaml rule es.confusions def esYearReading
export function esYearReading(at: SpanishAround) {
  const tokens = at.tokens;
  const prev = at.prev();
  const next = at.next();
  const plural = tokens[at.i].lower === "anos";
  return (
    (esIsCount(tokens[at.i - 1]) && !tokens[at.i].broken) ||
    /^(?:pasado|próximo|siguiente|anterior|entrante|nuevo|que)$/u.test(next) ||
    (plural && /^(?:pasados|próximos|siguientes|anteriores|venideros)$/u.test(next)) ||
    /^(?:cada|este|ese|aquel|primer|último|próximo|pasado|medio|nuevo|todo|esos|estos|aquellos|varios|muchos|pocos|algunos|siguientes|últimos|primeros)$/u.test(
      prev,
    ) ||
    (plural &&
      /^(?:ochenta|noventa|setenta|sesenta|cincuenta|cuarenta|treinta|veinte)$/u.test(next)) ||
    (esIsCount(tokens[at.i + 1]) &&
      !tokens[at.i + 1].broken &&
      /^(?:el|del|al|los)$/u.test(prev)) ||
    (prev === "el" && at.prev(2) === "todo") ||
    (prev === "por" && at.endsAfter() && [2, 3].some((k) => esIsCount(tokens[at.i - k]))) ||
    ((prev === "al" || prev === "por" || prev === "del") &&
      at.endsAfter() &&
      /^(?:veces|vez|días|semanas|meses|euros|dólares|€|\$)$/u.test(
        at.tokens[at.i - 2]?.lower ?? "",
      ))
  );
}

// es.yaml rule es.confusions def esParent
export function esParent(at: SpanishAround) {
  const next = at.next();
  const before = at.tokens[at.i - 1];
  const after = at.tokens[at.i + 1];
  return /^(?:mi|tu)$/u.test(at.prev())
    ? esFiniteVerb(next) && !esAttribute(next)
    : (!before || at.tokens[at.i].broken || /^[.!?¡¿…]$/u.test(before.text)) &&
        (!after || /^[,!]$/u.test(after.text));
}

// es.yaml rule es.confusions def esPlainE
export function esPlainE(at: SpanishAround) {
  const token = at.tokens[at.i];
  const after = at.tokens[at.i + 1];
  return (
    token.text === "e" &&
    !!after?.word &&
    !after.broken &&
    /^\p{Ll}/u.test(after.text) &&
    !!at.tokens[at.i - 1]?.word &&
    !ES_LETTER_BEFORE.has(at.prev()) &&
    !ES_LETTER_AFTER.has(after.lower) &&
    at.tokens[at.i + 2]?.text !== "-"
  );
}

// es.yaml rule es.confusions def esPerfectHe
export function esPerfectHe(at: SpanishAround) {
  const next = at.next();
  if (!(next === "ido" || esIsPerfectParticiple(next))) return null;
  return ES_CLITICS.has(at.prev())
    ? ["he"]
    : at.tokens[at.i].lower === "e" && !/^h?i/u.test(next) && esPlainE(at)
      ? ["he"]
      : (ES_BEFORE_HE.has(at.prev()) || at.starts) && !esIsNoun(next)
        ? ["he"]
        : null;
}

// es.yaml rule es.confusions def esStrayE
export function esStrayE(at: SpanishAround) {
  const next = at.next();
  if (!(esPlainE(at) && !/^h?[iy]/u.test(next))) return null;
  return esIsInfinitive(next) || (esFiniteVerb(next) && !esIsNoun(next))
    ? ["y"]
    : ES_DETERMINERS.has(next)
      ? ["es", "en", "y"]
      : ["el", "en", "de", "y"];
}

// es.yaml rule es.confusions def esInfinitiveAfter
export function esInfinitiveAfter(at: SpanishAround) {
  const next = at.next();
  return next !== "haber" && (esIsInfinitive(next) || esIsInfinitive(esPlain(next)));
}

// es.yaml rule es.confusions def esCasoClitics
export function esCasoClitics(at: SpanishAround, k: number): number {
  return k < 5 && /^(?:no|me|te|se|le|les|lo|los|nos|os)$/u.test(at.next(k))
    ? esCasoClitics(at, k + 1)
    : k;
}

// es.yaml rule es.confusions def esCasoDe
export function esCasoDe(at: SpanishAround) {
  if (!(at.prev() === "el" && at.prev(2) === "en" && at.next() === "que")) return null;
  const verb = at.next(esCasoClitics(at, 2));
  return esSubjunctiveLike(verb) || /(?:[ai]era|[ai]ese|[áé]ramos|[áé]semos)[sn]?$/u.test(verb)
    ? ["caso de"]
    : null;
}

// es.yaml rule es.confusions def esAra
export function esAra(at: SpanishAround) {
  return esIsInfinitive(at.next())
    ? ["para"]
    : /^(?:me|te|se|le|les|nos|os)$/u.test(at.prev())
      ? ["hará"]
      : at.next() === "mismo"
        ? ["ahora"]
        : null;
}

// es.yaml rule es.confusions def esTalTan
export function esTalTan(at: SpanishAround) {
  if (!ES_SER_ESTAR.has(at.prev())) return null;
  const next = at.next();
  const adjective =
    esAttribute(next) || esIsGenderedEntry(next) || /(?:ble|fácil|ícil)$/u.test(next);
  return ES_TAN_ADVERBS.has(next)
    ? ["tan"]
    : adjective && !esParticiple(next) && !esFiniteVerb(next)
      ? ["tan"]
      : null;
}

// es.yaml rule es.confusions def esHayHa
export function esHayHa(at: SpanishAround) {
  const next = at.next();
  const verbal =
    at.starts &&
    (esIsInfinitive(at.next(2)) ||
      ES_DETERMINERS.has(at.next(2)) ||
      /^(?:que|muy|tarde|pronto|temprano|ya|bien|mal|mucho|hoy|ayer|aquí|allí)$/u.test(at.next(2)));
  return at.tokens[at.i - 1]?.text === "¡" && (next === "de" || next === "del")
    ? ["ay"]
    : !esIsPerfectParticiple(next) || esIsNoun(next)
      ? null
      : /^(?:nadie|alguien|ninguno|ninguna|ningún)$/u.test(at.next(2))
        ? null
        : ES_CLITICS.has(at.prev()) || at.prev() === "no" || verbal || !esAttribute(next)
          ? ["ha"]
          : null;
}

// es.yaml rule es.confusions def esHazHas
export function esHazHas(at: SpanishAround) {
  const prev = at.prev();
  if (ES_DETERMINERS.has(prev) || ES_PREPOSITIONS.has(prev)) return null;
  const next = at.next();
  return esIsPerfectParticiple(next) && (!esIsNoun(next) || ES_CLITICS.has(prev))
    ? ["has"]
    : next === "de" && esIsInfinitive(at.next(2))
      ? ["has"]
      : null;
}

// es.yaml rule es.confusions def esSeClitic
export function esSeClitic(at: SpanishAround) {
  const next = at.next();
  if (!(next && !at.tokens[at.i + 1].broken)) return null;
  const form = esParticiple(next);
  return /^(?:mi|mis|tu|tus|su|sus|nuestro|nuestra|nuestros|nuestras)$/u.test(next)
    ? ["de"]
    : !form || !/[ai]d[oa]s?$/u.test(next)
      ? null
      : ES_CONFUSION_MODALS.has(at.prev())
        ? esIsNoun(next)
          ? null
          : ["ser"]
        : !form.feminine && !form.plural
          ? ["se ha"]
          : null;
}

// es.yaml rule es.confusions def esApunto
export function esApunto(at: SpanishAround) {
  const prev = at.prev();
  if (ES_CLITICS.has(prev) || prev === "yo" || prev === "lo") return null;
  return at.next() === "de" && esIsInfinitive(at.next(2))
    ? ["a punto"]
    : /^(?:estaba|estaban|está|están|estar|estoy|estás|estamos|todo|puesta|poner|ponerlo|ponerla|ponerlos|ponerlas)$/u.test(
          prev,
        ) && at.endsAfter()
      ? ["a punto"]
      : null;
}

// es.yaml rule es.confusions def esEntorno
export function esEntorno(at: SpanishAround) {
  const prev = at.prev();
  if (!prev || ES_DETERMINERS.has(prev) || ES_PREPOSITIONS.has(prev) || ES_CONJUNCTIONS.has(prev))
    return null;
  if (esAttribute(prev)) return null;
  if (esIsNoun(prev) && !esVerbLike(prev)) return null;
  return /^(?:a|al|de|del|suyo|suya|mío|tuyo|nuestro)$/u.test(at.next()) || at.endsAfter()
    ? ["en torno"]
    : null;
}

// es.yaml rule es.confusions def esOlaHola
export function esOlaHola(at: SpanishAround) {
  const next = at.tokens[at.i + 1];
  return /^(?:decir|decirle|decirte|dije|dijo|digo|dice|saludar)$/u.test(at.prev()) &&
    at.endsAfter()
    ? ["hola"]
    : at.starts &&
        (!next ||
          /^[,!]$/u.test(next.text) ||
          (next.word && /^\p{Lu}/u.test(next.text)) ||
          /^(?:qué|cómo|quién)$/u.test(next.lower))
      ? ["hola"]
      : null;
}

// es.yaml rule es.confusions def esElEn
export function esElEn(at: SpanishAround) {
  const noun = at.next(2);
  return /^(?:la|las)$/u.test(at.next()) &&
    at.tokens[at.i + 2]?.text === noun &&
    esIsNoun(noun) &&
    !esFiniteVerb(noun) &&
    !esVerbLike(noun) &&
    !/^(?:bemol|sostenido|mayor|menor|natural)$/u.test(noun)
    ? ["en"]
    : null;
}

// es.yaml rule es.confusions def esHaberAVer
export function esHaberAVer(at: SpanishAround) {
  const next = at.next();
  const nextToken = at.tokens[at.i + 1];
  const before = at.tokens[at.i - 1];
  const prev = at.prev();
  const motion =
    ES_IR.has(prev) || prev === "fue" || /^(?:llev|acompañ|mand|envi|vin|vien)\p{L}+$/u.test(prev);
  return (!before || at.tokens[at.i].broken || /^[.!?¡…«“"]$/u.test(before.text)) &&
    (/^(?:si|qué|quién|quiénes|cuántos|cuántas|cuánto|cuándo|cómo|dónde|por)$/u.test(next) ||
      nextToken?.text === ",")
    ? ["a ver"]
    : !(motion || /^(?:empez|comenz|empiez|comienz)\p{L}+$/u.test(prev)) ||
        !next ||
        esIsPerfectParticiple(next)
      ? null
      : ES_DETERMINERS.has(next) || /^(?:buen|buenos|buenas|mucho|mucha|muchos|muchas)$/u.test(next)
        ? prev === "fue"
          ? null
          : ES_IR.has(prev) || !motion
            ? ["a ver", "a haber"]
            : ["a ver"]
        : ES_CLITICS.has(next) || !motion
          ? null
          : ["a ver"];
}

// es.yaml rule es.confusions def esEchar
export function esEchar(at: SpanishAround, fix: string) {
  const prev = at.prev();
  return at.next() === "de" && at.next(2) === "menos" && (at.endsAfter(2) || at.next(3) === "a")
    ? [fix]
    : /^(?:me|te|le|les|nos|os|se)$/u.test(prev)
      ? [fix]
      : !/^(?:lo|la|los|las)$/u.test(prev)
        ? null
        : !/^hech[oa]s?$/u.test(at.tokens[at.i].lower) || (prev === "lo" && !fix.endsWith("o"))
          ? [fix]
          : null;
}

// es.yaml rule es.confusions def esGoVerb
export function esGoVerb(at: SpanishAround, fix: string) {
  if (ES_DETERMINERS.has(at.prev()) || ES_PREPOSITIONS.has(at.prev())) return null;
  const next = at.next();
  return (next === "a" || next === "al") &&
    /^(?:que|cuando|si|ojalá|lo|me|te|se|nos)$/u.test(at.prev())
    ? [fix]
    : esIsGerund(next)
      ? [fix]
      : null;
}

// es.yaml rule es.confusions def esSubjunctiveHaber
export function esSubjunctiveHaber(at: SpanishAround, fix: string) {
  const before = [1, 2, 3].map((k) => at.prev(k));
  const trigger = before
    .slice(0, before.indexOf("que") + 1 || 0)
    .every((word, k, all) => k === all.length - 1 || word === "no" || ES_CLITICS.has(word));
  const next = at.next();
  return (before[0] === "que" && before[1] === "para") || before[0] === "ojalá"
    ? [fix]
    : before[0] === "se" &&
        (before[1] === "que" || (before[1] === "no" && before[2] === "que")) &&
        esIsPerfectParticiple(at.next()) &&
        /^(?:nada|algo)$/u.test(at.next(2))
      ? [fix]
      : before[0] !== "que" &&
          before[0] !== "no" &&
          (!ES_CLITICS.has(before[0]) || before[0] === "se")
        ? null
        : !trigger || !before.includes("que")
          ? null
          : esIsPerfectParticiple(next)
            ? [fix]
            : /^(?:más|menos|algo|alguien|nada|nadie|un|una|unos|unas|mucho|mucha|muchos|muchas)$/u.test(
                  next,
                ) && before[0] === "que"
              ? [fix]
              : null;
}

// es.yaml rule es.confusions def esLocatedHallar
export function esLocatedHallar(at: SpanishAround, fix: string) {
  if (!(at.prev() === "se")) return null;
  const next = at.next();
  return next === "en"
    ? [fix]
    : esAround(at.tokens, at.i - 1).starts &&
        /^(?:ubicad|situad|instalad|sitiad|localizad)[oa]s?$/u.test(next)
      ? [fix]
      : null;
}

// es.yaml rule es.confusions def esCalledName
export function esCalledName(at: SpanishAround, fix: string) {
  if (!/^(?:me|te|se|nos|os)$/u.test(at.prev())) return null;
  const next = at.tokens[at.i + 1];
  return next?.word && !next.broken && /^\p{Lu}/u.test(next.text)
    ? [fix]
    : at.prev(2) === "cómo" && at.endsAfter()
      ? [fix]
      : null;
}

// es.yaml rule es.confusions def esDeshecho
export function esDeshecho(at: SpanishAround, word: string) {
  return (word === "desecho" && ES_HABER.has(at.prev())) ||
    /^(?:está|están|estaba|estaban|estoy|estás|parece|parecía|quedó|quedé)$/u.test(at.prev())
    ? [word.replace("desech", "deshech")]
    : null;
}

// es.yaml rule es.confusions def esGoingA
export function esGoingA(at: SpanishAround) {
  return esInfinitiveAfter(at) && !ES_DETERMINERS.has(at.prev())
    ? [`${at.tokens[at.i].lower} a`]
    : null;
}

// es.yaml rule es.confusions def ES_CONFUSION_CHECKS
export const ES_CONFUSION_CHECKS = new Map([
  ["ano", (at: SpanishAround) => (esYearReading(at) ? ["año"] : null)],
  ["e", (at: SpanishAround) => esPerfectHe(at) ?? esStrayE(at)],
  ["eh", esPerfectHe],
  [
    "aya",
    (at: SpanishAround) =>
      esIsPerfectParticiple(at.next()) && !ES_DETERMINERS.has(at.prev()) ? ["haya"] : null,
  ],
  ["ayan", (at: SpanishAround) => (esIsPerfectParticiple(at.next()) ? ["hayan"] : null)],
  ["caso", esCasoDe],
  [
    "bastantes",
    (at: SpanishAround) =>
      ES_SER.has(at.prev()) && esAttribute(at.next())?.plural && !esIsNoun(at.next())
        ? ["bastante"]
        : null,
  ],
  ["ara", esAra],
  [
    "través",
    (at: SpanishAround) =>
      /^(?:de|del)$/u.test(at.next()) && !/^(?:a|al|de|por)$/u.test(at.prev()) && !at.starts
        ? ["a través"]
        : null,
  ],
  ["ven", (at: SpanishAround) => (ES_CONFUSION_MODALS.has(at.prev()) ? ["ver"] : null)],
  ["podo", (at: SpanishAround) => (esInfinitiveAfter(at) ? ["puedo"] : null)],
  ["podes", (at: SpanishAround) => (esInfinitiveAfter(at) ? ["puedes", "podés"] : null)],
  ["poden", (at: SpanishAround) => (esInfinitiveAfter(at) ? ["pueden"] : null)],
  [
    "ora",
    (at: SpanishAround) =>
      /^(?:la|una|media|cada|qué|esta|esa|buena|mala|primera|última)$/u.test(at.prev()) &&
      !esIsInfinitive(at.next())
        ? ["hora"]
        : null,
  ],
  [
    "ah",
    (at: SpanishAround) =>
      at.starts
        ? null
        : esIsPerfectParticiple(at.next())
          ? ["ha"]
          : ES_IR.has(at.prev()) && esInfinitiveAfter(at)
            ? ["a"]
            : null,
  ],
  [
    "ay",
    (at: SpanishAround) =>
      at.prev() === "no" || (at.next() === "que" && esIsInfinitive(at.next(2))) ? ["hay"] : null,
  ],
  ["mama", (at: SpanishAround) => (esParent(at) ? ["mamá"] : null)],
  ["papa", (at: SpanishAround) => (esParent(at) ? ["papá"] : null)],
  ["tal", esTalTan],
  ["voy", esGoingA],
  ["vas", esGoingA],
  ["va", esGoingA],
  ["vamos", esGoingA],
  ["vais", esGoingA],
  ["van", esGoingA],
  ["iba", esGoingA],
  ["ibas", esGoingA],
  ["íbamos", esGoingA],
  ["ibais", esGoingA],
  ["iban", esGoingA],
  ["anos", (at: SpanishAround) => (esYearReading(at) ? ["años"] : null)],
  [
    "echo",
    (at: SpanishAround) =>
      ES_HABER.has(at.prev()) || /^(?:está|parece|bien|mal)$/u.test(at.prev()) ? ["hecho"] : null,
  ],
  ["hecho", (at: SpanishAround) => esEchar(at, "echo")],
  ["hecha", (at: SpanishAround) => esEchar(at, "echa")],
  ["hechas", (at: SpanishAround) => esEchar(at, "echas")],
  ["hechan", (at: SpanishAround) => esEchar(at, "echan")],
  ["hechamos", (at: SpanishAround) => esEchar(at, "echamos")],
  ["hay", esHayHa],
  ["haz", esHazHas],
  [
    "sobretodo",
    (at: SpanishAround) =>
      ES_DETERMINERS.has(at.prev()) || ES_PREPOSITIONS.has(at.prev()) ? null : ["sobre todo"],
  ],
  ["desecho", (at: SpanishAround) => esDeshecho(at, "desecho")],
  ["desecha", (at: SpanishAround) => esDeshecho(at, "desecha")],
  ["desechos", (at: SpanishAround) => esDeshecho(at, "desechos")],
  ["desechas", (at: SpanishAround) => esDeshecho(at, "desechas")],
  ["se", esSeClitic],
  ["valla", (at: SpanishAround) => esGoVerb(at, "vaya")],
  ["vallas", (at: SpanishAround) => esGoVerb(at, "vayas")],
  ["vallan", (at: SpanishAround) => esGoVerb(at, "vayan")],
  ["vallamos", (at: SpanishAround) => esGoVerb(at, "vayamos")],
  ["halla", (at: SpanishAround) => esSubjunctiveHaber(at, "haya")],
  ["hallan", (at: SpanishAround) => esSubjunctiveHaber(at, "hayan")],
  ["hallas", (at: SpanishAround) => esSubjunctiveHaber(at, "hayas")],
  ["haya", (at: SpanishAround) => esLocatedHallar(at, "halla")],
  ["hayan", (at: SpanishAround) => esLocatedHallar(at, "hallan")],
  ["apunto", esApunto],
  ["entorno", esEntorno],
  [
    "cuidad",
    (at: SpanishAround) =>
      /^(?:la|mi|tu|su|nuestra|vuestra|esta|esa|aquella|una|gran|cada|otra|misma|propia)$/u.test(
        at.prev(),
      )
        ? ["ciudad"]
        : null,
  ],
  ["lamo", (at: SpanishAround) => esCalledName(at, "llamo")],
  ["lamas", (at: SpanishAround) => esCalledName(at, "llamas")],
  ["lama", (at: SpanishAround) => esCalledName(at, "llama")],
  ["lamamos", (at: SpanishAround) => esCalledName(at, "llamamos")],
  ["ola", esOlaHola],
  ["el", esElEn],
  [
    "hola",
    (at: SpanishAround) =>
      /^(?:una|la|gran|esta|esa|aquella|otra|cada|primera|segunda|nueva)$/u.test(at.prev())
        ? ["ola"]
        : null,
  ],
  ["haber", esHaberAVer],
]);

// es.yaml rule es.confusions def esComparative
export function esComparative(at: SpanishAround) {
  return [1, 2, 3].some((k) => /^(?:más|menos|mayor|menor|mejor|peor|tanto)$/u.test(at.prev(k)));
}

// es.yaml rule es.confusions def esAVer
export function esAVer(tokens: SpanishTokens, i: number) {
  const ver = tokens[i + 1];
  if (!(tokens[i].lower === "a" && ver?.word && !ver.broken)) return null;
  const m = /^(ver|vér)((?:me|te|se|nos|os|le|les|lo|los|la|las){0,2})$/u.exec(ver.lower);
  if (!m) return null;
  const prev = esAround(tokens, i);
  if (!(prev.starts || ES_PERFECT_BEFORE.test(prev.prev()))) return null;
  const next = tokens[i + 2];
  if (!(
    (/^(?:pod|deb|pued|pud)\p{L}*$/u.test(prev.prev()) && !next?.broken) ||
    (next?.word && !next.broken && esIsPerfectParticiple(next.lower) && !esIsNoun(next.lower))
  ))
    return null;
  return `hab${m[1] === "vér" ? "é" : "e"}r${m[2]}`;
}

// es.yaml rule es.verbForms def ES_SENSES
export const ES_SENSES = /^(?:huel\p{L}*|ol\p{L}*|sab\p{L}*|sup\p{L}*)$/u;

// es.yaml rule es.verbForms def ES_PRONOMINAL
export const ES_PRONOMINAL =
  /^(?:alegr|quej|enter|acord|acuerd|olvid|hart|arrepent|arrepient|convenc)\p{L}*$/u;

// es.yaml rule es.verbForms def ES_SAYING
export const ES_SAYING =
  /^(?:pienso|piensa|piensas|pensamos|piensan|pensaba|pensé|pensó|creo|cree|crees|creemos|creen|creía|opino|opina|opinan|considero|considera|dijo|dije|dicen|digo|dice|decía|supongo|imagino|afirmó|afirma|comentó|asegura|aseguró|anunció|anunciar|explicó|declaró|parece|resulta|resultó)$/u;

// es.yaml rule es.verbForms def ES_VF_MODALS
export const ES_VF_MODALS =
  /^(?:deb(?:e|en|o|es|emos|ía|ías|ían|ería|erían|erías|eríamos|ió|ieron|erá|erán|erás)|suel(?:e|en|o|es)|sol(?:ía|ían|íamos)|pued(?:e|en|o|es)|pod(?:emos|ía|ías|ían|ría|rían|rías|rá|rán|rás)|gust(?:a|aba|aría|aban|an))$/u;

// es.yaml rule es.verbForms def ES_VF_TENER
export const ES_VF_TENER = /^(?:t(?:ien|eng|en|uv|endr)\p{L}*|hay|había|habrá|habría)$/u;

// es.yaml rule es.verbForms def ES_PAST_OR_CONDITIONAL
export const ES_PAST_OR_CONDITIONAL =
  /(?:aba|abas|aban|ábamos|rías?|rían|ríamos|aron|ieron|asteis|isteis|aste|iste)$/u;

// es.yaml rule es.verbForms def ES_IRREGULAR_FUTURE
export const ES_IRREGULAR_FUTURE = [
  ["tener", "tendrá"],
  ["poner", "pondrá"],
  ["salir", "saldrá"],
  ["venir", "vendrá"],
  ["valer", "valdrá"],
  ["poder", "podrá"],
  ["querer", "querrá"],
  ["saber", "sabrá"],
  ["caber", "cabrá"],
  ["haber", "habrá"],
  ["hacer", "hará"],
  ["decir", "dirá"],
] as const;

// es.yaml rule es.verbForms def ES_PERFECT_FOR
export const ES_PERFECT_FOR = new Map([
  ["me", ["he", "ha"]],
  ["te", ["ha", "he"]],
  ["se", ["ha", "han"]],
  ["le", ["ha", "he"]],
  ["les", ["ha", "he"]],
  ["nos", ["ha", "hemos"]],
  ["os", ["ha", "habéis"]],
]);

// es.yaml rule es.verbForms def esGerundOf
export function esGerundOf(word: string) {
  const ado = /^(\p{L}+)ado$/u.exec(word);
  const ido1 = /^(\p{L}+)ído$/u.exec(word);
  const ido = /^(\p{L}+)ido$/u.exec(word);
  return ado ? `${ado[1]}ando` : ido1 ? `${ido1[1]}yendo` : ido ? `${ido[1]}iendo` : null;
}

// es.yaml rule es.verbForms def esPerfectOf
export function esPerfectOf(word: string, nominal: boolean) {
  const agreement = esParticiple(word);
  const ando = /^(\p{L}+)ando$/u.exec(word);
  const iendo = /^(\p{L}+)iendo$/u.exec(word);
  const aron = /^(\p{L}+)aron$/u.exec(word);
  const ieron = /^(\p{L}+)ieron$/u.exec(word);
  return agreement && (agreement.feminine || agreement.plural) && !nominal
    ? word.replace(/[oa]s?$/u, "o")
    : ando && esIsGerund(word) && esIsVerb(`${ando[1]}ar`)
      ? `${ando[1]}ado`
      : iendo && esIsGerund(word) && (esIsVerb(`${iendo[1]}er`) || esIsVerb(`${iendo[1]}ir`))
        ? `${iendo[1]}ido`
        : aron && esIsVerb(`${aron[1]}ar`)
          ? `${aron[1]}ado`
          : ieron && (esIsVerb(`${ieron[1]}er`) || esIsVerb(`${ieron[1]}ir`))
            ? `${ieron[1]}ido`
            : null;
}

// es.yaml rule es.verbForms def esFinitePerfect
export function esFinitePerfect(word: string) {
  if (word.length < 4 || !esFiniteVerb(word) || esIsInfinitive(word) || esIsGerund(word))
    return null;
  if (esIsNoun(word)) return null;
  if (esParticiple(word)?.feminine === false && /[ai]do$/u.test(word)) return null;
  const ar = /^(\p{L}{2,}?)(?:o|a|as|an|e|es|en|é|ó|aste|ad|amos)$/u.exec(word);
  const erIr = /^(\p{L}{2,}?)(?:o|e|es|en|í|ió|iste|ed|id|emos|imos)$/u.exec(word);
  const found = [
    ...new Set(
      [
        ar && esIsVerb(`${ar[1]}ar`) ? `${ar[1]}ado` : null,
        erIr && (esIsVerb(`${erIr[1]}er`) || esIsVerb(`${erIr[1]}ir`)) ? `${erIr[1]}ido` : null,
      ].filter((fix) => fix !== null),
    ),
  ];
  return found.length === 1 ? found[0] : null;
}

// es.yaml rule es.verbForms def esAuxiliaryA
export function esAuxiliaryA(at: SpanishAround) {
  const prev = at.prev();
  const next = at.next();
  const typed = at.tokens[at.i].text;
  const nextToken = at.tokens[at.i + 1];
  if (!(esIsPerfectParticiple(next) && !nextToken.broken)) return false;
  if (!(typed === "a" || (typed === "A" && at.starts))) return false;
  if (/^(?:cubierto|salvo|medio|pedido|contado)$/u.test(next)) return false;
  return ES_BEFORE_AUXILIARY.has(prev) || /^(?:alguien|nadie|quien)$/u.test(prev)
    ? true
    : at.starts && !esIsNoun(next) && (ES_DETERMINERS.has(at.next(2)) || at.next(2) === "de")
      ? true
      : /^(?:el|la|un|una|este|esta|ese|esa|mi|tu|su)$/u.test(at.prev(2)) &&
          esIsNoun(prev) &&
          !esFiniteVerb(prev)
        ? true
        : !esAttribute(prev)?.plural &&
          !esIsNoun(next) &&
          !esGenderedForm(next) &&
          !ES_SENSES.test(prev) &&
          !ES_CLITICS.has(prev) &&
          /^\p{Ll}/u.test(nextToken.text) &&
          at.tokens[at.i + 2]?.text !== "-" &&
          ![1, 2, 3, 4].some((k) => at.prev(k) === "de");
}

// es.yaml rule es.verbForms def esAfterHaber
export function esAfterHaber(at: SpanishAround, word: string, prev: string, next: string) {
  if (!(ES_HABER.has(prev) && !/^\p{N}/u.test(at.tokens[at.i - 2]?.text ?? ""))) return null;
  const existential =
    ES_EXISTENTIAL.has(prev) &&
    !ES_REFLEXIVE.has(at.prev(2)) &&
    !(
      prev === "haber" &&
      !esIsNoun(word) &&
      (/^(?:\p{L}+(?:mos|is)|puedo|debo|podría|debería)$/u.test(at.prev(2)) ||
        (/^\p{L}+n$/u.test(at.prev(2)) && esSubjectAt(at, 3)) ||
        at.prev(3) === "se")
    );
  const nominal =
    existential || (esIsNoun(next) && !ES_QUANTIFIER_AFTER.has(next) && !/^\p{N}/u.test(next));
  const fix = esPerfectOf(word, nominal) ?? (existential ? null : esFinitePerfect(word));
  return fix && fix !== word ? [fix] : null;
}

// es.yaml rule es.verbForms def esGerundForParticiple
export function esGerundForParticiple(at: SpanishAround, word: string, prev: string, next: string) {
  const gerund = esGerundOf(word);
  return prev === "ido" &&
    /^(?:hemos|habéis|han|habíamos|habíais|habían)$/u.test(at.prev(2)) &&
    /[ai]do$/u.test(word) &&
    esParticiple(word) &&
    gerund
    ? [gerund, `${word}s`]
    : esIsPerfectParticiple(word) &&
        !esIsNoun(word) &&
        !esGenderedForm(word) &&
        (((prev === "ido" || prev === "estado") && ES_PERFECT.has(at.prev(2))) ||
          ((prev === "ido" || prev === "estado") && ES_CLITICS.has(at.prev(2))) ||
          (ES_ESTAR.has(prev) && /^(?:me|te|se|nos|os)$/u.test(at.prev(2))) ||
          (ES_ESTAR.has(prev) &&
            esIsInfinitive(next) &&
            /^(?:intent|trat|procur|pens)ado$/u.test(word))) &&
        gerund
      ? [gerund]
      : null;
}

// es.yaml rule es.verbForms def esAuxiliaryForms
export function esAuxiliaryForms(at: SpanishAround, word: string, prev: string, next: string) {
  const after = at.tokens[at.i + 1];
  return word === "a" && esAuxiliaryA(at)
    ? ["ha"]
    : word === "e" &&
        at.tokens[at.i].text === word &&
        esIsPerfectParticiple(next) &&
        (ES_BEFORE_AUXILIARY.has(prev) || prev === "yo")
      ? ["he"]
      : word === "e" && at.starts && at.tokens[at.i].text === "E" && esIsPerfectParticiple(next)
        ? ["he"]
        : word === "e" && esIsPerfectParticiple(next) && !/^h?i/u.test(next)
          ? ["he"]
          : word === "ha" && next
            ? esIsInfinitive(next) && next !== "haber"
              ? ["a"]
              : (ES_IR.has(prev) || /^(?:volver|regresar|llegar|venir|ir)$/u.test(prev)) &&
                  after.word &&
                  !esIsPerfectParticiple(next) &&
                  !/^(?:de|que|sido|estado)$/u.test(next)
                ? ["a"]
                : /^(?:este|esta|estos|estas|ese|esa|esos|esas|los|las|el|la)$/u.test(next) &&
                    !/^\p{Lu}/u.test(after.text) &&
                    !at.starts
                  ? ["a"]
                  : null
            : null;
}

// es.yaml rule es.verbForms def esVerbFormCheck
export function esVerbFormCheck(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const prev = at.prev();
  const next = at.next();
  return (
    esAfterHaber(at, word, prev, next) ??
    esGerundForParticiple(at, word, prev, next) ??
    esAuxiliaryForms(at, word, prev, next)
  );
}

// es.yaml rule es.verbForms def esReflexive
export function esReflexive(at: SpanishAround) {
  const verb = at.prev();
  const k = /(?:ado|ido)$/u.test(verb) && ES_HABER.has(at.prev(2)) ? 3 : 2;
  const pronoun = at.prev(k);
  return /(?:ar|er|ir|ndo)(?:se|me|te|nos|os)$/u.test(verb)
    ? true
    : !ES_REFLEXIVE.has(pronoun)
      ? false
      : k === 3
        ? true
        : pronoun === "me"
          ? /(?:o|é|aba|ía)$/u.test(verb)
          : pronoun === "te"
            ? /s(?:te)?$/u.test(verb)
            : pronoun === "nos"
              ? /mos$/u.test(verb)
              : pronoun === "os"
                ? /is$/u.test(verb)
                : !/(?:o|é|mos)$/u.test(verb);
}

// es.yaml rule es.verbForms def esDeQue
export function esDeQue(tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  const word = tokens[i].lower;
  const prev = at.prev();
  return word === "que" &&
    !tokens[i].broken &&
    ((prev === "cuenta" && ES_DAR.has(at.prev(2))) ||
      (ES_PRONOMINAL.test(prev) && esReflexive(at)) ||
      (/^segur[oa]s?$/u.test(prev) &&
        /^(?:estoy|estás|está|estamos|están|estaba|estaban|estar)$/u.test(at.prev(2))))
    ? { to: i, fix: "de que" }
    : word === "de" &&
        at.next() === "que" &&
        tokens[i + 1]?.text === "que" &&
        (ES_SAYING.test(prev) ||
          (ES_IMPERSONAL.has(prev) && /^(?:es|era|sería|será|fue)$/u.test(at.prev(2))) ||
          (/^(?:alegra|alegró|alegraba)$/u.test(prev) &&
            /^(?:me|te|le|nos|os|les)$/u.test(at.prev(2))))
      ? { to: i + 1, fix: "que" }
      : null;
}

// es.yaml rule es.verbForms def esThirdPerson
export function esThirdPerson(infinitive: string) {
  const irregular = ES_IRREGULAR_FUTURE.find((pair) => infinitive.endsWith(pair[0]));
  const future = irregular
    ? `${infinitive.slice(0, -irregular[0].length)}${irregular[1]}`
    : `${infinitive}á`;
  const stem = infinitive.slice(0, -2);
  const lastVowel = /[aeiouáéíóú](?=[^aeiouáéíóú]*$)/u.exec(stem)?.[0];
  return irregular || !lastVowel || /[eo]/u.test(lastVowel) || /[iu]$/u.test(stem)
    ? [future]
    : [`${stem}${infinitive.endsWith("ar") ? "a" : "e"}`, future];
}

// es.yaml rule es.verbForms def esCliticSlot
export function esCliticSlot(tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  const clitic = tokens[i].lower;
  const next = at.next();
  const nextToken = tokens[i + 1];
  if (!(ES_PERFECT_FOR.has(clitic) && next && /^\p{Ll}/u.test(nextToken.text))) return null;
  if (clitic === "se" || /^(?:un|el|del|al|mi|tu|su)$/u.test(at.prev())) return null;
  const inf = /^(\p{L}+?)([aei])r(nos)?$/u.exec(next);
  const noun = esReadNoun(next);
  return inf && esIsVerb(`${inf[1]}${inf[2]}r`)
    ? inf[3]
      ? clitic === "nos"
        ? {
            from: i + 1,
            to: i + 1,
            fixes: [`${inf[1]}${ES_FIRST_PLURAL[`${inf[2]}r`]}`],
            key: "review_msg_spanish_verb_form" as const,
          }
        : null
      : {
          from: i + 1,
          to: i + 1,
          fixes: esThirdPerson(`${inf[1]}${inf[2]}r`),
          key: "review_msg_spanish_verb_form" as const,
        }
    : esIsPerfectParticiple(next) &&
        !esIsVerb(`${next.slice(0, -1)}ar`) &&
        next !== "hecho" &&
        at.next(2) !== "de" &&
        !/^(?:nos|os)$/u.test(clitic)
      ? {
          from: i,
          to: i + 1,
          fixes: ES_PERFECT_FOR.get(clitic)!.map((aux) => `${clitic} ${aux} ${next}`),
          key: "review_msg_spanish_verb_form" as const,
        }
      : !noun?.gender ||
          !/^(?:le|les|nos|os)$/u.test(clitic) ||
          esParticiple(next) ||
          noun.plural !== (clitic !== "le") ||
          (/ia[sn]?$/u.test(next) &&
            ["er", "ir"].some((e) => esIsVerb(next.replace(/ia[sn]?$/u, e)))) ||
          esFiniteVerb(next) ||
          esSubjunctiveLike(next) ||
          esIsGerund(next) ||
          ES_VERB_NOUNS.has(next) ||
          ES_DETERMINERS.has(next)
        ? null
        : {
            from: i,
            to: i,
            fixes: [ES_ARTICLE_FORMS[noun.gender][noun.plural ? 1 : 0]],
            key: "review_msg_spanish_pronoun_article" as const,
          };
}

// es.yaml rule es.verbForms def esPrepositionVerb
export function esPrepositionVerb(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const prev = at.prev();
  if (!(/^(?:a|al|de|del|para|sin|por|tras|hasta)$/u.test(prev) && !esIsNoun(word))) return null;
  const ase = /^(\p{L}{3,}?)ase$/u.exec(word);
  const iese = /^(\p{L}{2,}?)iese$/u.exec(word);
  const iese1 = iese ? [`${iese[1]}er`, `${iese[1]}ir`].find((v) => esIsVerb(v)) : undefined;
  const bare = /^(\p{L}{3,}?)([ae])$/u.exec(word);
  const bare1 =
    prev === "a" && bare && ES_IR.has(at.prev(2)) && !esGenderedForm(word)
      ? (bare[2] === "a" ? [`${bare[1]}ar`] : [`${bare[1]}er`, `${bare[1]}ir`]).find((v) =>
          esIsVerb(v),
        )
      : undefined;
  return ase && esIsVerb(`${ase[1]}ar`) ? `${ase[1]}arse` : iese1 ? `${iese1}se` : (bare1 ?? null);
}

// es.yaml rule es.verbForms def esAttributeAfter
export function esAttributeAfter(next: string) {
  return (
    !!next &&
    !esFiniteVerb(next) &&
    (ES_DETERMINERS.has(next) ||
      ES_VF_DEGREE.has(next) ||
      !!esAttribute(next) ||
      esIsInvariantEntry(next) ||
      esIsNoun(next) ||
      /^(?:mejor|peor|mayor|menor)$/u.test(next))
  );
}

// es.yaml rule es.verbForms def esGovernedVerb
export function esGovernedVerb(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const prev = at.prev();
  if (!(prev && /^\p{Ll}/u.test(at.tokens[at.i].text) && !ES_NOT_GOVERNED.has(word))) return null;
  const governs =
    (ES_VF_MODALS.test(prev) &&
      !ES_ALONE_AFTER.has(at.prev(2)) &&
      (!/^gust/u.test(prev) || (ES_CLITICS.has(at.prev(2)) && !ES_ALONE_AFTER.has(at.prev(3))))) ||
    (prev === "que" && ES_VF_TENER.test(at.prev(2))) ||
    (prev === "de" && ES_HABER_DE.has(at.prev(2))) ||
    (word === "se" && prev === "a" && ES_IR.has(at.prev(2)));
  if (!governs) return null;
  if (prev === "que" && /^(?:qué|cuál|cuáles)$/u.test(at.prev(3)) && esFiniteVerb(word))
    return null;
  const past = /^(\p{L}{2,}?)(ara|ase|iera|iese)$/u.exec(word);
  const ending = past
    ? past[2].startsWith("a")
      ? "ar"
      : ["er", "ir"].find((e) => esIsVerb(`${past[1]}${e}`))
    : undefined;
  return word === "se"
    ? esAttributeAfter(at.next())
      ? "ser"
      : null
    : ES_CLITICS.has(word) || ES_DETERMINERS.has(word) || ES_DETERMINER.has(word)
      ? null
      : esIsNoun(word) || esGenderedForm(word) || esParticiple(word) || esIsInfinitive(word)
        ? null
        : past && ending && esIsVerb(`${past[1]}${ending}`)
          ? `${past[1]}${ending}${past[2] === "ase" ? "se" : ""}`
          : /[ae]$/u.test(word) && esIsVerb(`${word}r`)
            ? `${word}r`
            : esPresentInfinitive(word);
}

// es.yaml rule es.verbForms def esStrayFinite
export function esStrayFinite(at: SpanishAround) {
  const word = at.tokens[at.i].lower;
  const k = ES_CLITICS.has(at.prev()) && at.prev() !== "se" ? 2 : 1;
  const prev = at.prev(k);
  if (!(/^(?:de|del|en|con|desde|sin)$/u.test(prev) && /^\p{Ll}+$/u.test(at.tokens[at.i].text)))
    return false;
  return k === 2
    ? prev === "del" || prev === "desde"
      ? false
      : (ES_PAST_OR_CONDITIONAL.test(word) ||
          /^\p{L}{2,}(?:amos|emos|imos)$/u.test(word) ||
          (/^\p{L}{2,}(?:e|es)$/u.test(word) &&
            esSubjunctiveLike(word) &&
            !esGenderedForm(word))) &&
        esFiniteVerb(word) &&
        !esIsNoun(word) &&
        !esAttribute(word) &&
        !esIsInfinitive(word)
    : at.tokens[at.i - 2]?.text === "-" || ES_AFTER_PREPOSITION.has(word)
      ? false
      : /^(?:la|una|letra)$/u.test(at.prev(2))
        ? false
        : /^(?:es|eres|soy|somos|estoy|hay|fue|fui|fueron)$/u.test(word)
          ? true
          : ES_PAST_OR_CONDITIONAL.test(word) &&
            esFiniteVerb(word) &&
            !esIsNoun(word) &&
            !esAttribute(word) &&
            !esIsInfinitive(word) &&
            !esIsGerund(word) &&
            !ES_CLITICS.has(word) &&
            !ES_DETERMINERS.has(word) &&
            !ES_DETERMINER.has(word) &&
            !ES_PREPOSITIONS.has(word) &&
            !/^(?:que|como|cuando|donde|si|no|ya|más|menos|bien|mal|tal|tan|sí)$/u.test(word);
}

// es.yaml rule es.verbForms def esStrayFiniteFinding
export function esStrayFiniteFinding(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const token = tokens[i];
  const prep =
    ES_CLITICS.has(tokens[i - 1].lower) && tokens[i - 2]?.word ? tokens[i - 2] : tokens[i - 1];
  const desde = prep.lower === "desde";
  const found = esReplaceToken(
    ctx,
    desde ? prep : esSpan(ctx, prep, token),
    desde ? ["desde que"] : [],
    "spanishConfusions",
    desde ? "review_msg_spanish_verb_form" : "review_msg_spanish_preposition_verb",
    token,
  );
  return found && (desde ? found : { ...found, warningOnly: true as const });
}

// es.yaml rule es.prefixes def esKnownWord
export function esKnownWord(word: string) {
  return (
    !(word.startsWith("des") && ES_NOUN_ENDING.test(word)) &&
    (esIsNoun(word) || esIsGenderedEntry(word) || !!esGenderedForm(word))
  );
}

// es.yaml rule es.splitCompounds def ES_MAL_VERBS
export const ES_MAL_VERBS =
  /^(?:interpret|gast|trat|cri|vend|her|entend|entiend|acostumbr)\p{L}+$/u;

// es.yaml rule es.splitCompounds def esObjectCompound
export function esObjectCompound(head: string, tail: string) {
  const noun = esReadNoun(tail);
  const nounHead = esReadNoun(head);
  return noun &&
    !noun.paired &&
    (!nounHead || nounHead.gender === "f") &&
    (noun.plural || esIsNoun(esJoinPrefix(head, tail)))
    ? esJoinPrefix(head, tail)
    : null;
}

// es.yaml rule es.splitCompounds def esSplitCompound
export function esSplitCompound(
  at: SpanishAround,
  det: string,
  head: string,
  tail: string,
  hyphen: boolean,
) {
  return ES_MASCULINE_DETERMINERS.has(det) && /[^aeiou][ae]$/u.test(head) && esFiniteVerb(head)
    ? esObjectCompound(head, tail)
    : !hyphen &&
        (head === "sobre" || (head === "mal" && ES_MAL_VERBS.test(tail))) &&
        !esIsNoun(tail) &&
        !esAttribute(tail)
      ? (esFiniteVerb(tail) && esFiniteVerb(esJoinPrefix(head, tail)) && !ES_CLITICS.has(tail)) ||
        (head === "sobre" &&
          ES_CLITICS.has(at.prev()) &&
          esFiniteVerb(tail) &&
          !esIsNoun(tail) &&
          !ES_CLITICS.has(tail))
        ? esJoinPrefix(head, tail)
        : null
      : null;
}

// es.yaml rule es.porque def ES_KNOWING
export const ES_KNOWING =
  /^(?:sé|sabe|sabes|sabemos|saben|sabía|sabías|sabían|saber|supe|supo|sepa|sepas|sepan|entienda|entiendas|comprenda|pregunto|pregunta|preguntas|preguntan|preguntó|preguntaba|preguntarse|preguntarle|entiendo|entiendes|entiende|entender|comprendo|comprende|comprender|explica|explicar|explícame|explicarme|ignoro|averiguar|imagino|imagina|recuerdo|recuerda|dime|dinos|decirme|decirnos|aquí)$/u;

// es.yaml rule es.porque def ES_FINITE_LOOK
export const ES_FINITE_LOOK = /\p{L}{2,}(?:rá|rán|ré|rás|ría|rían|ríamos|remos)$/u;

// es.yaml rule es.porque def esPorqueSpelling
export function esPorqueSpelling(tokens: SpanishTokens, i: number) {
  const token = tokens[i];
  const next = tokens[i + 1];
  return token.lower === "porque" || token.lower === "porqué"
    ? { end: i, kind: token.lower }
    : token.lower === "porques" || token.lower === "porqués"
      ? { end: i, kind: "plural" }
      : token.lower !== "por" || !next?.word || next.broken
        ? null
        : next.lower === "que"
          ? { end: i + 1, kind: "por que" }
          : next.lower === "qué"
            ? { end: i + 1, kind: "por qué" }
            : next.lower === "qués"
              ? { end: i + 1, kind: "plural" }
              : null;
}

// es.yaml rule es.porque def esPorqueVerbs
export function esPorqueVerbs(tokens: SpanishTokens, j: number, end: number): number {
  return j >= tokens.length || j >= end || tokens[j].broken || /^[?.!]$/u.test(tokens[j].text)
    ? 0
    : (tokens[j].word && esFiniteVerb(tokens[j].lower) && !ES_PORQUE_CLOSED.has(tokens[j].lower)
        ? 1
        : 0) + esPorqueVerbs(tokens, j + 1, end);
}

// es.yaml rule es.porque def esPorqueFix
export function esPorqueFix(
  tokens: SpanishTokens,
  i: number,
  spelling: { end: number; kind: string },
): string[] | null {
  const at = esAround(tokens, i);
  const skip = /^\p{L}{3,}mente$/u.test(at.prev()) || at.prev() === "ya" ? 1 : 0;
  const prev = at.prev(1 + skip);
  const opens = tokens[i - 1]?.text === "¿" || (tokens[i - 2]?.text === "¿" && at.prev() === "y");
  const asked =
    ((prev === "es" || prev === "era") && ES_ASKING_NOUNS.has(at.prev(2 + skip))) ||
    (prev === "de" && ES_ASKING_NOUNS.has(at.prev(2 + skip)));
  const after = esAround(tokens, spelling.end);
  const next = after.next();
  const closes = after.endsAfter() || next === "de" || next === "del";
  const negated = at.prev(2) === "no" || at.prev(3) === "no";
  const verb = /^(?:él|ella|ellos|ellas|usted|yo|tú|se|me|te|le|les|lo|la|nos)$/u.test(next)
    ? after.next(2)
    : next;
  const subject = at.prev(2 + skip) === "se" ? 3 + skip : 2 + skip;
  return spelling.kind === "plural"
    ? ES_PLURAL_DETS.has(prev) && tokens[i].lower !== "porqués"
      ? ["porqués"]
      : null
    : ES_SINGULAR_DETS.has(prev)
      ? spelling.kind !== "porqué" && closes
        ? ["porqué"]
        : null
      : ES_PLURAL_DETS.has(prev)
        ? closes
          ? ["porqués"]
          : null
        : spelling.kind === "por qué"
          ? null
          : asked
            ? ["por qué"]
            : spelling.kind === "porqué"
              ? opens || ES_KNOWING.test(prev)
                ? ["por qué"]
                : esFiniteVerb(prev) && next && !closes
                  ? ["porque", "por qué"]
                  : null
              : spelling.kind === "por que"
                ? opens || ES_KNOWING.test(prev) || ES_REASON.has(next)
                  ? ["por qué"]
                  : ES_NEED.has(prev) && negated && esIsInfinitive(next)
                    ? ["por qué"]
                    : (esFiniteVerb(prev) || esIsInfinitive(prev)) &&
                        !esReadNoun(prev) &&
                        !!verb &&
                        esFiniteVerb(verb) &&
                        !esSubjunctiveLike(verb)
                      ? ["porque", "por qué"]
                      : null
                : spelling.kind === "porque" &&
                    /^(?:razón|razones|motivo|motivos)$/u.test(prev) &&
                    ES_DETERMINER.has(at.prev(2)) &&
                    next &&
                    ![3, 4].some((k) =>
                      /^(?:(?:ten|tien|tuv|tend|d[aiáé])\p{L}*|con|sin)$/u.test(at.prev(k)),
                    )
                  ? ["por que"]
                  : opens &&
                      next &&
                      !(esPorqueVerbs(tokens, spelling.end + 1, spelling.end + 16) > 1)
                    ? ["por qué"]
                    : ES_KNOWING.test(prev) && at.prev(subject) === "no" && next
                      ? ["por qué"]
                      : ES_TELL.has(prev) && next
                        ? ["por qué"]
                        : ES_NEED.has(prev) && negated && esIsInfinitive(next)
                          ? ["por qué"]
                          : null;
}

// es.yaml rule es.porque def esPorquePhrase
export function esPorquePhrase(tokens: SpanishTokens, i: number) {
  const spelling = esPorqueSpelling(tokens, i);
  if (!(spelling && !tokens[spelling.end].broken)) return null;
  const fix = esPorqueFix(tokens, i, spelling);
  if (!fix) return null;
  return { end: spelling.end, fix };
}

// es.yaml rule es.porque def esPorqueVerbAt
export function esPorqueVerbAt(token: SpanishToken | undefined) {
  return (
    !!token?.word &&
    !ES_PORQUE_CLOSED.has(token.lower) &&
    esFiniteVerb(token.lower) &&
    !esReadNoun(token.lower)
  );
}

// es.yaml rule es.porque def esNegatedBefore
export function esNegatedBefore(tokens: SpanishTokens, j: number, stop: number): boolean {
  return j < 0 || j <= stop
    ? false
    : /^[.;:!?¿¡]$/u.test(tokens[j].text) || tokens[j + 1].broken
      ? false
      : tokens[j].lower === "no" || tokens[j].lower === "nunca" || tokens[j].lower === "tampoco"
        ? true
        : esNegatedBefore(tokens, j - 1, stop);
}

// es.yaml rule es.porque def esSinoWord
export function esSinoWord(tokens: SpanishTokens, i: number, at: SpanishAround) {
  const next = tokens[i + 1];
  if (!(next?.word && !next.broken && next.lower !== "que")) return null;
  if (ES_DETERMINER.has(at.prev()) || /^(?:hace|hacía|hay)$/u.test(next.lower)) return null;
  if (ES_PREPOSITIONS.has(next.lower)) return null;
  const verb = ES_CLITICS.has(next.lower) ? tokens[i + 2] : next;
  if (!(verb && esPorqueVerbAt(verb) && !esSubjunctiveLike(verb.lower))) return null;
  return {
    end: i,
    fix: at.starts || !esNegatedBefore(tokens, i - 1, i - 12) ? ["si no"] : ["si no", "sino que"],
  };
}

// es.yaml rule es.porque def esSiNoScan
export function esSiNoScan(tokens: SpanishTokens, j: number, end: number): boolean {
  return j >= tokens.length || j >= end
    ? false
    : tokens[j].broken || /^[.;:!?]$/u.test(tokens[j].text)
      ? true
      : tokens[j].text === "," || ES_CLITICS.has(tokens[j].lower)
        ? false
        : tokens[j].lower === "para" && tokens[j + 1]?.lower === "de"
          ? false
          : !tokens[j].word ||
              ES_PREPOSITIONS.has(tokens[j].lower) ||
              ES_PORQUE_CLOSED.has(tokens[j].lower)
            ? esSiNoScan(tokens, j + 1, end)
            : ES_FINITE_LOOK.test(tokens[j].lower) ||
                (esFiniteVerb(tokens[j].lower) && !esReadNoun(tokens[j].lower))
              ? false
              : esSiNoScan(tokens, j + 1, end);
}

// es.yaml rule es.porque def esSiNo
export function esSiNo(tokens: SpanishTokens, i: number, at: SpanishAround) {
  if (!(tokens[i].lower === "si" && at.next() === "no" && !tokens[i + 1].broken)) return null;
  const after = tokens[i + 2];
  const before = tokens[i - 1];
  if (!(after?.word && !after.broken && before && !/^[.;:!?¿¡]$/u.test(before.text))) return null;
  if (!(!tokens[i].broken && esNegatedBefore(tokens, i - 1, i - 12))) return null;
  if (!(after.lower === "que" || esSiNoScan(tokens, i + 2, i + 10))) return null;
  return { end: i + 1, fix: ["sino"] };
}

// es.yaml rule es.porque def esSino
export function esSino(tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  return tokens[i].lower === "sino" ? esSinoWord(tokens, i, at) : esSiNo(tokens, i, at);
}

// es.yaml rule es.clauseConfusions def ES_DAR_FORMS
export const ES_DAR_FORMS =
  /^d(?:a|as|an|ar|ado|ando|aba|aban|ió|ieron|ará|arán|aría|arían|é|en|iera|ieran)$/u;

// es.yaml rule es.clauseConfusions def ES_ALTA_AUXILIARIES
export const ES_ALTA_AUXILIARIES =
  /^(?:ha|han|he|has|hemos|había|habían|habrán|va|van|iba|iban|a|puede|pueden|deben|debe|quieren|quiere)$/u;

// es.yaml rule es.clauseConfusions def ES_LETTING
export const ES_LETTING = /^(?:permit|dej|impid|imped|prohib)\p{L}*$/u;

// es.yaml rule es.clauseConfusions def ES_IRREGULAR_PARTICIPLE
export const ES_IRREGULAR_PARTICIPLE =
  /(?:decir|hacer|poner|scribir|volver|solver|cubrir|abrir|romper|morir|^ver|prever|proveer|freír|imprimir)$/u;

// es.yaml rule es.clauseConfusions def ES_SUBJUNCTIVE_AR
export const ES_SUBJUNCTIVE_AR = [
  [/c$/u, "qu"],
  [/g$/u, "gu"],
  [/z$/u, "c"],
] as const;

// es.yaml rule es.clauseConfusions def ES_IRREGULAR_SUBJUNCTIVE_STEM
export const ES_IRREGULAR_SUBJUNCTIVE_STEM =
  /^(?:ser|dar|ver|ir|caer|saber|haber|caber|valer)$|(?:decir|tener|venir|poner|salir|traer|cer|cir|ger|gir|guir)$/u;

// es.yaml rule es.clauseConfusions def esJoinedEnclitic
export function esJoinedEnclitic(verb: string, pronoun: string) {
  const m = /^(\p{L}*?)([ae])(ndo)$/u.exec(verb);
  return esIsInfinitive(verb) || /[áé]ndo/u.test(verb)
    ? `${verb}${pronoun}`
    : m
      ? `${m[1]}${ES_STRESS[m[2]]}${m[3]}${pronoun}`
      : null;
}

// es.yaml rule es.clauseConfusions def esSeparatedEnclitic
export function esSeparatedEnclitic(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  const verb = tokens[i].lower;
  const pronoun = at.next();
  if (!(ES_ENCLITIC.has(pronoun) && !tokens[i + 1].broken)) return null;
  if (!(esIsGerund(verb) || esIsInfinitive(verb))) return null;
  const after = at.next(2);
  const ends =
    esIsBoundary(tokens[i + 2]) &&
    tokens[i + 2]?.text !== "," &&
    !/^["“«'‘]$/u.test(tokens[i + 2]?.text ?? "");
  if (!ends && (!ES_PREPOSITIONS.has(after) || /^(?:de|del|que)$/u.test(after))) return null;
  if (tokens[i + 2]?.broken) return null;
  const fix = esJoinedEnclitic(verb, pronoun);
  if (!fix) return null;
  return esReplaceToken(
    ctx,
    esSpan(ctx, tokens[i], tokens[i + 1]),
    [fix],
    "spanishConfusions",
    "review_msg_spanish_enclitic",
  );
}

// es.yaml rule es.clauseConfusions def esAPunto
export function esAPunto(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  if (!(tokens[i].lower === "apunto" && at.next() === "de" && esIsInfinitive(at.next(2))))
    return null;
  return esReplaceToken(
    ctx,
    tokens[i],
    ["a punto"],
    "spanishConfusions",
    "review_msg_spanish_confusion",
    tokens[i + 2],
  );
}

// es.yaml rule es.clauseConfusions def esAltaAuxiliaries
export function esAltaAuxiliaries(at: SpanishAround, k: number): number {
  return k <= 3 && ES_ALTA_AUXILIARIES.test(at.next(k)) ? esAltaAuxiliaries(at, k + 1) : k;
}

// es.yaml rule es.clauseConfusions def esAltaClitic
export function esAltaClitic(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const clitic = tokens[i].lower;
  if (!/^(?:le|les|lo|la|los|las)$/u.test(clitic)) return null;
  const at = esAround(tokens, i);
  if (!(at.prev() !== "se")) return null;
  const k = esAltaAuxiliaries(at, 1);
  if (!ES_DAR_FORMS.test(at.next(k))) return null;
  const phrase = `${at.next(k + 1)} ${at.next(k + 2)}`;
  const fixes =
    /^de (?:alta|baja)$/u.test(phrase) && clitic === "les"
      ? ["los", "las"]
      : /^(?:el alta|la baja)$/u.test(phrase) && !clitic.startsWith("le")
        ? [clitic.endsWith("s") ? "les" : "le"]
        : [];
  if (!fixes.length) return null;
  return esReplaceToken(
    ctx,
    tokens[i],
    fixes,
    "spanishConfusions",
    "review_msg_spanish_alta",
    tokens[i + k + 2],
  );
}

// es.yaml rule es.clauseConfusions def esPermitQue
export function esPermitQue(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  if (!(tokens[i].lower === "que" && ES_LETTING.test(at.prev()))) return null;
  const det = at.next();
  if (!/^(?:el|la|los|las|mi|mis|tu|tus|su|sus|este|esta|estos|estas)$/u.test(det)) return null;
  const noun = at.next(2);
  if (!noun || !esReadNoun(noun) || esIsInfinitive(noun) || !esIsInfinitive(at.next(3)))
    return null;
  return det === "el"
    ? esReplaceToken(
        ctx,
        esSpan(ctx, tokens[i], tokens[i + 1]),
        ["al"],
        "spanishConfusions",
        "review_msg_spanish_verb_form",
        tokens[i + 3],
      )
    : esReplaceToken(
        ctx,
        tokens[i],
        ["a"],
        "spanishConfusions",
        "review_msg_spanish_verb_form",
        tokens[i + 3],
      );
}

// es.yaml rule es.clauseConfusions def esPrepositionFinite
export function esPrepositionFinite(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const at = esAround(tokens, i);
  const word = tokens[i].lower;
  if (!(ES_GOVERNING.has(at.prev()) && !ES_NOT_FINITE_HERE.has(word) && !tokens[i].broken))
    return null;
  if (!(/^\p{Ll}/u.test(tokens[i].text) && word.length >= 4)) return null;
  if (esIsNoun(word) || esReadNoun(word) || esParticiple(word) || esIsInfinitive(word)) return null;
  if (!(esFiniteVerb(word) && /a$/u.test(word))) return null;
  if (!(at.endsAfter() || ES_PREPOSITIONS.has(at.next()))) return null;
  const infinitive = esPresentInfinitive(word);
  if (!infinitive) return null;
  return esReplaceToken(
    ctx,
    tokens[i],
    [infinitive],
    "spanishConfusions",
    "review_msg_spanish_verb_form",
    tokens[i - 1],
  );
}

// es.yaml rule es.clauseConfusions def esPerfectInfinitive
export function esPerfectInfinitive(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  if (!(ES_AUXILIARY_ONLY.has(esAround(tokens, i).prev()) && /^\p{Ll}+$/u.test(tokens[i].text)))
    return null;
  const word = tokens[i].lower;
  const m = /^(\p{L}+?)([aeií])r$/u.exec(word);
  if (
    !m ||
    !esIsVerb(word.replace("í", "i")) ||
    esIsNoun(word) ||
    ES_IRREGULAR_PARTICIPLE.test(word)
  )
    return null;
  return esReplaceToken(
    ctx,
    tokens[i],
    [m[2] === "a" ? `${m[1]}ado` : /[aeo]$/u.test(m[1]) ? `${m[1]}ído` : `${m[1]}ido`],
    "spanishConfusions",
    "review_msg_spanish_verb_form",
    tokens[i - 1],
  );
}

// es.yaml rule es.clauseConfusions def esCliticOrder
export function esCliticOrder(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  const first = tokens[i];
  const second = tokens[i + 1];
  if (!(/^(?:me|te|nos|os)$/u.test(first.lower) && second?.lower === "se" && !second.broken))
    return null;
  const verb = esAround(tokens, i + 1).next();
  if (!(verb && esFiniteVerb(verb) && !esIsNoun(verb) && !ES_CLITICS.has(verb))) return null;
  return esReplaceToken(
    ctx,
    esSpan(ctx, first, second),
    [`se ${first.lower}`],
    "spanishConfusions",
    "review_msg_spanish_clitic_order",
    tokens[i + 2],
  );
}

// es.yaml rule es.clauseConfusions def esNegativeImperative
export function esNegativeImperative(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  if (!(esAround(tokens, i).prev() === "no" && /^\p{Ll}+$/u.test(tokens[i].text))) return null;
  const word = tokens[i].lower;
  const m = /^(\p{L}{2,}?)([aei])d$/u.exec(word);
  if (!m || (esIsNoun(word) && !ES_NOUN_ENDING.test(word))) return null;
  const infinitive = `${m[1]}${m[2]}r`;
  if (!esIsVerb(infinitive)) return null;
  if (ES_IRREGULAR_SUBJUNCTIVE_STEM.test(infinitive) && !/[^g]uir$/u.test(infinitive)) return null;
  const rule = ES_SUBJUNCTIVE_AR.find((pair) => pair[0].test(m[1]));
  return esReplaceToken(
    ctx,
    tokens[i],
    [
      /[^g]uir$/u.test(infinitive)
        ? `${m[1]}yáis`
        : m[2] === "a"
          ? `${rule ? m[1].replace(rule[0], rule[1]) : m[1]}éis`
          : `${m[1]}áis`,
    ],
    "spanishConfusions",
    "review_msg_spanish_negative_imperative",
    tokens[i - 1],
  );
}

// es.yaml rule es.clauseConfusions def esDoubledSuperlative
export function esDoubledSuperlative(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  if (!(tokens[i].lower === "muy")) return null;
  const next = tokens[i + 1];
  if (!(next?.word && !next.broken && /^\p{L}{3,}ísim[oa]s?$/u.test(next.lower))) return null;
  return esReplaceToken(
    ctx,
    esSpan(ctx, tokens[i], next),
    [next.lower],
    "spanishConfusions",
    "review_msg_spanish_double_superlative",
    next,
  );
}

// es.yaml rule es.clauseConfusions def esDadoQue
export function esDadoQue(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  if (!(tokens[i].lower === "dado")) return null;
  const at = esAround(tokens, i);
  if (!(at.next() === "a" && at.next(2) === "que" && at.starts)) return null;
  return esReplaceToken(
    ctx,
    esSpan(ctx, tokens[i], tokens[i + 2]),
    ["dado que"],
    "spanishConfusions",
    "review_msg_contextual_grammar",
    tokens[i + 2],
  );
}

// es.yaml rule es.typography def esKnown
export function esKnown(word: string) {
  return esIsNoun(word) || !!esAttributeOf(word) || esIsGenderedEntry(word) || esVerbLike(word);
}

// es.yaml rule es.typography def esISound
export function esISound(word: string) {
  return /^h?[ií](?![aeoáéó])/iu.test(word);
}

// es.yaml rule es.typography def esOSound
export function esOSound(word: string) {
  return /^h?[oó]/iu.test(word) || /^8/u.test(word);
}

// es.yaml rule es.typography def esConjunction
export function esConjunction(at: SpanishAround, token: SpanishToken) {
  const next = at.tokens[at.i + 1];
  if (!(next && !next.broken && (next.word || /^\p{N}/u.test(next.text)))) return null;
  if (!(at.tokens[at.i - 1]?.text !== "¿")) return null;
  const after = next.text;
  if (/^\p{Ll}+\p{Lu}/u.test(after)) return null;
  const foreignH =
    /^h/iu.test(after) &&
    (/^\p{Lu}/u.test(after) && token.lower === "y"
      ? true
      : /^\p{Ll}/u.test(after) &&
        (!esKnown(after.toLowerCase()) || at.tokens[at.i + 2]?.text === "-"));
  if (foreignH) return null;
  const prev = at.prev();
  return token.lower === "y" && esISound(after)
    ? "e"
    : token.lower === "e" && !esISound(after) && /^h?[ií]/iu.test(after)
      ? "y"
      : token.lower === "o" &&
          esOSound(after) &&
          (!/^\p{N}/u.test(after) || /^\p{N}/u.test(at.tokens[at.i - 1]?.text ?? ""))
        ? "u"
        : token.text === "u" &&
            next.word &&
            prev &&
            !/^(?:la|una|letra|vocal)$/u.test(prev) &&
            esKnown(after.toLowerCase()) &&
            !esOSound(after)
          ? "o"
          : null;
}

// es.yaml rule es.typography def esYearDot
export function esYearDot(at: SpanishAround, token: SpanishToken) {
  const m = /^([12])\.(\d{3})$/u.exec(token.text);
  if (!m) return null;
  const year = Number(m[1] + m[2]);
  if (!(year >= 1100 && year <= 2099)) return null;
  const prev = at.tokens[at.i - 1]?.text.toLowerCase() ?? "";
  const next = at.next();
  return /^(?:año|años|del)$/u.test(prev)
    ? m[1] + m[2]
    : !/^(?:de|en|para|desde|hasta|y|-)$/u.test(prev)
      ? null
      : !next || (!esIsNoun(next) && !esAttributeOf(next))
        ? m[1] + m[2]
        : null;
}

// es.yaml rule es.typography def esCapitalName
export function esCapitalName(at: SpanishAround, token: SpanishToken) {
  if (!(/^\p{Lu}\p{Ll}+$/u.test(token.text) && !at.starts)) return null;
  const word = token.lower;
  const prev = at.prev();
  const before = at.tokens[at.i - 2];
  return ES_MONTHS.has(word)
    ? (prev === "de" && !!before && /^\p{N}/u.test(before.text)) ||
      (/^(?:de|del)$/u.test(at.next()) && /^\p{N}|^año$/u.test(at.tokens[at.i + 2]?.text ?? "")) ||
      (/^(?:en|de|desde|hasta|y)$/u.test(prev) && at.endsAfter())
      ? word
      : null
    : ES_WEEKDAYS.has(word) || ES_SEASONS.has(word)
      ? /^(?:el|los|cada|este|próximo|pasado|del|al)$/u.test(prev) &&
        !/^\p{Lu}/u.test(at.tokens[at.i + 1]?.text ?? "") &&
        !(/^(?:de|del)$/u.test(at.next()) && /^\p{Lu}/u.test(at.tokens[at.i + 2]?.text ?? ""))
        ? word
        : null
      : null;
}

// es.yaml rule es.typography def esAcronymPlural
export function esAcronymPlural(text: string) {
  const m = /^(\p{Lu}{2,})(?:['’]?s|S)$/u.exec(text);
  return m && ES_ACRONYMS.has(m[1].toLowerCase()) ? m[1] : null;
}

// es.yaml rule es.impossibleDates def ES_WEEKDAY_LIST
export const ES_WEEKDAY_LIST = [
  "domingo",
  "lunes",
  "martes",
  "miércoles",
  "jueves",
  "viernes",
  "sábado",
];

// es.yaml rule es.impossibleDates def ES_DATED
export const ES_DATED = /(?:^|\s)(?:el|del|al|día|fecha|desde|hasta)\s{1,8}[*_~]{0,3}$/iu;

// es.yaml rule es.impossibleDates def ES_CODE_LABEL
export const ES_CODE_LABEL =
  /(?:^|[\s(])(?:n[º°o]\.?|núm\.?|número|#|ref\.?|código|expediente)\s*:?\s{0,8}$/iu;

// es.yaml rule es.impossibleDates def esShortMonth
export function esShortMonth(month: string) {
  return (
    ({ sept: 9, set: 9 } as Readonly<Record<string, number>>)[month.toLowerCase()] ??
    "ene|feb|mar|abr|may|jun|jul|ago|sep|sept|set|oct|nov|dic"
      .split("|")
      .indexOf(month.toLowerCase()) + 1
  );
}

// es.yaml rule es.impossibleDates def esDayFinding
export function esDayFinding(
  ctx: DetectContext,
  start: number,
  day: string,
  month: number,
  year: number | undefined,
) {
  const max = esDaysInMonth(month, year);
  if (Number(day) <= max || Number(day) > 31 || month < 1) return null;
  if (namedExampleBefore(ctx.text, start)) return null;
  const alternatives = month === 2 && year === undefined ? ["28", "29"] : [String(max)];
  return esFinding(
    "spanishTypography",
    "review_msg_spanish_date",
    start,
    start + day.length,
    alternatives,
    {
      bulkBlock: "ambiguous",
      ...(alternatives.length > 1 ? { requiresChoice: true as const } : {}),
    },
  );
}

// es.yaml rule es.impossibleDates def esWeekdayNoYear
export function esWeekdayNoYear(
  ctx: DetectContext,
  m: RegExpExecArray,
  dayStart: number,
  monthIndex: number,
) {
  const weekday = m[1];
  const day = m[3];
  const years = esYearsFor(monthIndex, Number(day), esContextYear(ctx.text, m.index, ctx.lang));
  const weekdays = [...new Set(years.map((y) => esWeekdayOf(y, monthIndex, Number(day))))];
  const typed = ES_WEEKDAY_LIST.indexOf(weekday.toLowerCase());
  if (!(years.length && !weekdays.includes(typed))) return null;
  const near = esNearestDayOn(years[0], monthIndex, Number(day), typed);
  return {
    ruleId: "spanishTypography" as const,
    messageKey: "review_msg_weekday_no_year" as const,
    range: { start: m.index, end: dayStart + day.length },
    alternatives: [
      ...weekdays.map((w) => `${esCarryCase(weekday, ES_WEEKDAY_LIST[w])}${m[2]}${day}`),
      ...(near === null ? [] : [`${weekday}${m[2]}${near}`]),
    ],
    requiresChoice: true as const,
    context: { start: m.index, end: m.index + m[0].length },
  };
}

// es.yaml rule es.typographyMarks def ES_NOT_ORDINAL_AFTER
export const ES_NOT_ORDINAL_AFTER =
  /^(?:cent|fahr|kel|grad|norte|sur|este|oeste|latitud|longitud|bajo)/u;

// es.yaml rule es.typographyMarks def esMarkFix
export function esMarkFix(m: RegExpExecArray, frame: FrameRef, fix: string | null) {
  if (!(fix && fix !== m[0])) return null;
  return esFinding("spanishTypography", frame.messageKey, m.index, m.index + m[0].length, [fix]);
}

// es.yaml rule es.typographyMarks def esMarkOpen
export function esMarkOpen(m: RegExpExecArray, ctx: DetectContext) {
  return m.index >= ctx.from && !namedExampleBefore(ctx.text, m.index);
}

// es.yaml rule es.typographyMarks def esClosingEnd
export function esClosingEnd(text: string, k: number, stop: number): number {
  const c = text[k];
  return k >= stop
    ? -1
    : c === "?" || c === "!"
      ? -3
      : c === "¿" || c === "¡" || c === "\n" || c === "￼" || c === "«" || c === '"'
        ? c === "\n"
          ? k
          : -2
        : (c === "." || c === "…") &&
            /^(?:[ \t]+\p{Lu}|[ \t]*(?:\n|$))/u.test(text.slice(k + 1, k + 12))
          ? /\p{Lu}\p{Ll}{0,3}$/u.test(text.slice(Math.max(0, k - 5), k))
            ? esClosingEnd(text, k + 1, stop)
            : k
          : k === text.length - 1
            ? text.length
            : esClosingEnd(text, k + 1, stop);
}

// es.yaml rule es.typographyMarks def esLastNonSpace
export function esLastNonSpace(text: string, k: number, floor: number): number {
  return k > floor && /\s/u.test(text[k]) ? esLastNonSpace(text, k - 1, floor) : k;
}

